// runs called it and how those calls ended.
export interface RoomToolUse {
  tool: string;
  action?: string;
  calls: number;
  refused: number;
  errors: number;
}

// RoomToolUseReply is GET /v1/tenant/jobs/tool-calls?from=&to=: the room
// tool calls of the organization's runs created in [FromMs, ToMs), most
// called first. Runs counts the runs read; Truncated says the read stopped
// at MaxToolUseRuns, so the counts cover only the newest runs (created
// from OldestMs on). Dropped counts calls the runs did not keep (beyond
// MaxRunToolCalls a run), which no row counts.
export interface RoomToolUseReply {
  fromMs: number;
  toMs: number;
  runs: number;
  truncated?: boolean;
  oldestMs?: number;
  dropped?: number;
  tools: RoomToolUse[];
}

// MaxToolUseRuns bounds the runs one tool use read reads.
export const MaxToolUseRuns = 5000;

// RunPreviewRunes bounds every text preview a run record carries.
export const RunPreviewRunes = 280;

// AgentRunRequest is the room message that requested the run.
export interface AgentRunRequest {
  // MessageSeq is the request's room sequence (jump-to-message target).
  messageSeq: number;
  clientMsgId?: string;
  // Text is a preview of the request (absent when redacted).
  text?: string;
  attachments?: number;
}

// AgentRunAgent is the addressed agent: owner/core/provider plus the target
// and the model options the request chose.
export interface AgentRunAgent {
  owner: string;
  core: string;
  provider: string;
  targetId?: string;
  model?: string;
  reasoningEffort?: string;
}

// AgentRunPhases are the run's phase timestamps (unix ms; absent = the phase
// never happened). Queued is the job's creation; Claimed the latest bridge
// claim; Started the first time a bridge began driving; FirstReply when the
// first visible reply was produced (bridge-reported); Finished when the job
// reached its terminal status (replied/failed/timed out/cancelled).
export interface AgentRunPhases {
  queuedAtMs: number;
  claimedAtMs?: number;
  startedAtMs?: number;
  firstReplyAtMs?: number;
  finishedAtMs?: number;
  updatedAtMs?: number;
}

// AgentRunReply summarizes the run's visible replies. MessageID/Text/AtMs
// describe the first reply; Count is how many the run posted. RoomSeq is the
// first reply's room sequence, resolved by the run detail route only.
export interface AgentRunReply {
  messageId?: string;
  roomSeq?: number;
  text?: string;
  atMs?: number;
  count?: number;
}

// AgentRunExpert is the expert of a run at the version the job pinned.
export interface AgentRunExpert {
  id: string;
  name?: string;
  version?: string;
}

// AgentRunUsage is the usage the run's replies reported, summed. Tokens and
// cost are present only when reported.
export interface AgentRunUsage {
  model?: string;
  inputTokens?: number;
  outputTokens?: number;
  costUsd?: number;
}

// AgentRun is one run record.
export interface AgentRun {
  jobId: string;
  roomId: string;
  roomName?: string;
  channelId?: string;
  // Requester asked for the run; Borrowed when that is not the agent owner.
  requester: string;
  borrowed?: boolean;
  status: AgentJobStatus;
  failureReason?: AgentJobFailureReason;
  error?: string;
  warning?: string;
  attempt?: number;
  // Attempts are the run's earlier attempts and why each was retried.
  attempts?: AgentJobAttempt[];
  request: AgentRunRequest;
  agent: AgentRunAgent;
  phases: AgentRunPhases;
  reply?: AgentRunReply;
  usage?: AgentRunUsage;
  // DispatchedBy is set when an agent dispatched this run through the room
  // tools (the parent job and the hop depth).
  dispatchedBy?: AgentRunDispatch;
  // Expert is the expert the agent wore for this run ("expert X v1.2 on
  // agent Y"); absent when the chat picked none.
  expert?: AgentRunExpert;
  // RoomExpert is the room's expert the turn wore under the chat's own,
  // recorded when the turn resolved it; absent when the room had none.
  roomExpert?: AgentRunExpert;
  // Tools are the MCP tool components the turn's session had
  // (AgentRunTools), by name; absent when none or reported by an older
  // bridge.
  tools?: string[];
  // Redacted marks a run whose request/reply text and diagnostics are
  // withheld because the viewer is not a member of the run's room.
  redacted?: boolean;
  // Diagnostics is the bridge's last raw status report: detail route only,
  // and only to the agent's owner and org admins (O4).
  diagnostics?: Record<string, unknown>;
}

// AgentRunsReply is GET /v1/rooms/{id}/jobs (scope room), GET /v1/my/jobs
// (scope self) and GET /v1/tenant/jobs (scope tenant). NextBefore is the
// opaque cursor of the next (older) page; absent on the last page.
export interface AgentRunsReply {
  scope: RunScope;
  runs: AgentRun[];
  nextBefore?: string;
}

// ---- wire/api_tokens.go ----

// ServiceSubjectPrefix is the reserved namespace of service identities (an API
// token's subject, a test account): svc:<name>, lowercase letters, digits and
// . _ - (the gateway enforces the rest).
export const ServiceSubjectPrefix = "svc:";

// APITokenCreateRequest is POST /v1/platform/api-tokens.
export interface APITokenCreateRequest {
  // Subject defaults to the caller; otherwise a svc:<name> service subject.
  subject?: string;
  label: string;
  ttlDays?: number;
  // TenantID is the tenant hint the exchanged session resolves in (default
  // the caller's session tenant).
  tenantId?: string;
}

// APITokenView is one token as listed (never the secret or its hash).
export interface APITokenView {
  id: string;
  subject: string;
  label: string;
  tenant?: string;
  createdBy: string;
  createdAtMs: number;
  expiresAtMs: number;
  lastUsedAtMs?: number;
  revokedAtMs?: number;
  revokedBy?: string;
  active: boolean;
}

// APITokensReply is GET /v1/platform/api-tokens.
export interface APITokensReply {
  tokens: APITokenView[];
}

// APITokenGrant is POST /v1/auth/api-token: a session only (no refresh
// token), so its holder keeps the API token to renew it.
export interface APITokenGrant {
  sessionToken: string;
  subject: string;
  tenant: string;
  role: string;
  rooms: string[];
  expiresAtMs: number;
}

// APITokenCreated answers a create: the token's view and the token itself,
// shown once.
export interface APITokenCreated extends APITokenView {
  token: string;
}

// ---- wire/apps.go ----

// AppDocWrite is an insert (POST) or a replace (PUT). Doc is the document's
// JSON object; stamps in it are ignored. Public opts the document into
// being readable by everyone holding the app (insert: default false;
// replace: unchanged when absent).
export interface AppDocWrite {
  doc: unknown;
  public?: boolean;
}

// AppDocPatch is a PATCH: Merge is a JSON merge patch (RFC 7396) and Inc
// adds numbers at top-level or dotted paths; Public as in AppDocWrite.
export interface AppDocPatch {
  merge?: unknown;
  $inc?: unknown;
  public?: boolean;
}

// AppDocPage is one page of a find. Next is the cursor of the following
// page (pass it as after=), empty on the last page.
export interface AppDocPage {
  docs: Record<string, unknown>[];
  next?: string;
}

// AppMe is who the caller is to the app: ID is their per-app pseudonym (the
// _by of what they write); Name their display name, for a signed-in
// member only.
export interface AppMe {
  id: string;
  name?: string;
  // Account is the caller's own verified account, for a signed-in caller
  // (a member, or a person who signed in to open an organization link);
  // absent for an anonymous visitor and for an agent
  // (docs/prd/2026-10-15-app-identity-schedules-notify-ai.md §3).
  account?: AppAccount;
}

// AppAccount is who a signed-in caller is: their login (the identity
// provider's subject, what they sign in with) and the email it asserted
// ("" when it asserted none).
export interface AppAccount {
  login: string;
  email?: string;
}

// AppDataStats is an app's usage, for its owners.
export interface AppDataStats {
  documents: number;
  bytes: number;
  collections: Record<string, number>;
  // Files and FileBytes are the files the app's pages uploaded.
  files: number;
  fileBytes: number;
}

// AppFile is a file an app's page uploaded (app.files.upload), as the app
// reads it: its id (what the app keeps in its own documents), name, type
// (the attachment type it was checked as) and size, and the stamps a
// document carries: _by (the uploader's per-app id), _createdAt, and
// _author for the app's owners only.
export interface AppFile {
  id: string;
  name: string;
  type: string;
  size: number;
  public: boolean;
  _by: string;
  _createdAt: number;
  _author?: string;
}

// AppDataWiped answers an owner's delete of all of an app's data.
export interface AppDataWiped {
  deleted: number;
}

// EventAppChanged is a transient room event (bnbloc-room): a document of
// one of the room's apps changed. It is never replayed or persisted and
// carries only AppChanged: an app's change feed (GET ~app/events at the
// gateway) re-fetches under its own read rights, so the feed leaks no
// content.
export const EventAppChanged = "app_changed";

// AppChanged is the payload of EventAppChanged and the data of each event
// of an app's change feed. Version is the document's version after the
// change, 0 when it was deleted; a wipe of all of the app's data names no
// collection and no id.
export interface AppChanged {
  appId: string;
  collection?: string;
  id?: string;
  version: number;
  // SourceJobID is the agent job whose agent wrote ("" for a person or a
  // visitor): what caused the change, read by the room's event tap (no
  // self-trigger) and never relayed to an app's change feed.
  sourceJobId?: string;
}

// AppVisitorToken answers POST /v1/public/shares/{token}/visitor: a signed
// visitor token bound to the share link and to one random visitor id (the
// participant a public link's app knows). The share page keeps it and hands
// it to the app frame (AppVisitorRequest / AppVisitorGrant); the SDK sends
// it in AppVisitorHeader.
export interface AppVisitorToken {
  token: string;
  expiresAtMs: number;
}

// AppVisitorRenew is the optional body of the visitor route: the token the
// share page holds. A valid token of the same link is renewed for the same
// visitor; anything else mints a new visitor.
export interface AppVisitorRenew {
  token?: string;
}

// AppVisitorHeader carries a public link's visitor token on an app data
// call: a header, never the URL, so the token stays out of access logs.
export const AppVisitorHeader = "X-Bnbloc-Visitor";

// The visitor handshake between the app frame (the SDK, ~app/sdk.js) and
// the share page hosting it, over window.postMessage. The frame's origin
// is opaque, so neither side can name the other's origin; each checks the
// message's source window instead:
//
// 	frame  -> parent: {type: AppVisitorRequest, v: AppHandshakeVersion}
// 	parent -> frame:  {type: AppVisitorGrant, v: AppHandshakeVersion, token: AppVisitorToken.token}
//
// The parent answers only a request whose event.source is its own app
// frame's window, and may send a grant unasked (after it renewed the
// token). The SDK accepts a grant only from window.parent.
export const AppVisitorRequest = "bnbloc.app.visitor.request";
export const AppVisitorGrant = "bnbloc.app.visitor";
export const AppHandshakeVersion = 1;

// The error codes of an app data call (httpx.ErrorBody code) the SDK acts
// on: it asks the share page for a visitor token and retries once.
// AppVisitorRequired: a public link's app call carried no visitor
// token (401).
export const AppVisitorRequired = "visitor_token_required";
// AppVisitorInvalid: the visitor token is forged, expired or another
// link's (401).
export const AppVisitorInvalid = "visitor_token_invalid";

// The formats of an owner's export of an app's data (GET
// /v1/rooms/{roomId}/apps/{artifactId}/export?collection=&format=): JSON
// is {"collections": {"<name>": [document, …]}} of every collection, or of
// the one named; CSV is one collection, its stamps first, then the other
// top-level fields in order of first appearance, nested values as their
// JSON text (internal/appdata export.go).
export const AppExportJSON = "json";
export const AppExportCSV = "csv";

// AppAIRequest is an app's ai call (POST ~app/ai): the app's own Prompt
// (its instruction to the model) and Input (the data to work on, fenced
// as data); JSON asks for a JSON object instead of text.
export interface AppAIRequest {
  prompt: string;
  input?: string;
  json?: boolean;
}

// AppAIReply is its answer: Text, or JSON for a json call.
export interface AppAIReply {
  text?: string;
  json?: Record<string, unknown>;
}

// The codes of an app's ai and notify refusals (httpx.ErrorBody.Code).
// AppSignInRequired: the call is for people who signed in, and the
// caller is an anonymous visitor (or an agent).
export const AppSignInRequired = "sign_in_required";
// AppAIUnavailable: no assist model, or the organization turned AI off.
export const AppAIUnavailable = "ai_unavailable";
// AppGroupsUnavailable: no notifier of the organization delivers to
// groups.
export const AppGroupsUnavailable = "groups_unavailable";

// AppNotifyRoom is the to of a notice for the room's members;
// AppNotifyGroupPrefix starts the to of a notice for a named group of the
// organization's notifier ("group:team-weekly").
export const AppNotifyRoom = "room";
export const AppNotifyGroupPrefix = "group:";
// MaxNotifyGroupLen bounds a group name, in characters.
export const MaxNotifyGroupLen = 64;

// AppNotifyRequest is an app's notify call (POST ~app/notify): To is
// AppNotifyRoom (the room's members), a list of logins in the
// organization, or "group:<name>" (a group the organization's notifier
// delivers to); Title and Text are plain text; URL, when set, must be on
// the deployment's own origin (default: the app's card in its room).
export interface AppNotifyRequest {
  to: unknown;
  title: string;
  text?: string;
  url?: string;
}

// AppNotifyReply answers it: how many people the notice was addressed to
// (each one's preferences and mutes still apply).
export interface AppNotifyReply {
  recipients: number;
}

// AppGroupsReply answers GET ~app/groups: the names of the group chats the
// room's members connected, for an owner's page to send to
// (to: "group:<name>"); empty for anyone else, who cannot send to one.
export interface AppGroupsReply {
  groups: string[];
}

// AppNotifyTargets is the room service's resolution of a notice's to
// (POST /internal/v1/app/notify-targets): the members it reaches, the
// app's title and the room's name.
export interface AppNotifyTargets {
  recipients: string[];
  // Group is the connected group chat a "group:<name>" notice goes to
  // (no recipients): its name, notifier and address.
  group?: string;
  groupNotifier?: string;
  groupAddress?: string;
  appTitle: string;
  roomName: string;
}

// RoomGroup is a group chat connected to a room (docs/prd/2026-10-15-app-
// identity-schedules-notify-ai.md §5a), as its members see it: the name
// notices address ("group:<name>"), the notifier that delivers to it, who
// connected it and when. The chat's address stays server-side.
export interface RoomGroup {
  name: string;
  notifier: string;
  connectedBy: string;
  createdAtMs: number;
}

// RoomGroupsReply lists a room's connected group chats.
export interface RoomGroupsReply {
  groups: RoomGroup[];
}

// RoomGroupConnectRequest asks for a code connecting a group chat under
// Name.
export interface RoomGroupConnectRequest {
  name: string;
}

// RoomGroupConnect is that code: posted in the group chat (where the
// organization's bot is a member) before ExpiresAtMs, it connects the chat.
export interface RoomGroupConnect {
  name: string;
  code: string;
  expiresAtMs: number;
}

// NotifierGroupBindRequest is a notifier's report of a connect code posted
// in a group chat (POST /v1/notifier/group-binds, signed like a reply):
// the code as typed and the notifier's own address of the chat.
export interface NotifierGroupBindRequest {
  code: string;
  address: string;
}

// NotifierGroupBindReply answers a bind: the room and the group's name (for
// the bot's confirmation in the chat).
export interface NotifierGroupBindReply {
  roomName: string;
  name: string;
}

// Bounds of a room's group chats.
export const MaxRoomGroups = 20;
export const MaxRoomGroupCodesOpen = 5;
export const MaxGroupAddressLen = 512;
// RoomGroupCodeTTLMs is how long a connect code binds.
export const RoomGroupCodeTTLMs = 600000;
// RoomGroupCodePrefix starts every connect code, so a notifier knows a
// message is one.
export const RoomGroupCodePrefix = "bnbloc-";

// ---- wire/artifacts.go ----

// Artifact is a room deliverable (spec, report, code, image, site) as room
// members see it. The tenant stays server-side. store.Artifact.View builds
// it.
export interface Artifact {
  artifactId: string;
  roomId: string;
  channelId: string;
  kind: string;
  title: string;
  language?: string;
  // MimeType / FileName are the current version's media type and display
  // name (the extension source).
  mimeType?: string;
  fileName?: string;
  currentVersion: number;
  createdBy: string;
  createdAtMs: number;
  updatedAtMs: number;
  // IsApp: the artifact is an interactive app, a site whose data space
  // exists or whose current version loads the app SDK (store.Artifact.IsApp,
  // the one rule; a client never re-derives it).
  isApp: boolean;
}

// ArtifactThumbnail is a stored preview image of a version (the bytes are
// served by the thumbnail route).
export interface ArtifactThumbnail {
  mimeType: string;
  width: number;
  height: number;
}

// ArtifactVersion is one immutable revision of an artifact. Lists omit
// Content; an inline version serves it per version, a blob version through
// the content route (never Content). The blob key and the tenant stay
// server-side. store.ArtifactVersion.View builds it.
export interface ArtifactVersion {
  artifactId: string;
  version: number;
  parentVersion: number;
  // ContentHash is the sha256 of the version's bytes.
  contentHash: string;
  content?: string;
  // Storage is "inline" or "blob".
  storage: string;
  sizeBytes: number;
  mimeType?: string;
  // SourceJobID / SourceSeq link the version to the agent job and the room
  // message that produced it (zero for a manual publish).
  sourceJobId?: string;
  sourceSeq?: number;
  summary?: string;
  authorUserId: string;
  createdAtMs: number;
  thumbnail?: ArtifactThumbnail;
  // EditedFrom is the version an edit request started from (0 = not an
  // edit); below ParentVersion when the file changed meanwhile.
  editedFrom?: number;
}

// ArtifactList is GET /v1/rooms/{id}/artifacts: newest-updated first;
// NextCursor pages on (absent on the last page). MaxBytes is the room's
// blob version cap, so a publisher skips a file the room would refuse.
export interface ArtifactList {
  artifacts: Artifact[];
  maxBytes: number;
  nextCursor?: string;
}

// ArtifactDetail is GET .../artifacts/{id}: the artifact and its newest
// versions (metadata only).
export interface ArtifactDetail {
  artifact: Artifact;
  versions: ArtifactVersion[];
}

// ArtifactReply answers a create (Version absent when it published none),
// a publish, and a blob publish whose bytes were already the current
// version (Unchanged, nothing new published).
export interface ArtifactReply {
  artifact: Artifact;
  version?: ArtifactVersion;
  unchanged?: boolean;
}

// ArtifactVersionReply is GET .../artifacts/{id}/versions/{n}.
export interface ArtifactVersionReply {
  version: ArtifactVersion;
}

// ArtifactThumbnailReply answers a thumbnail put: Stored is false when a
// thumbnail of higher rank was already stored (the version is unchanged).
export interface ArtifactThumbnailReply {
  version: ArtifactVersion;
  stored: boolean;
}

// ArtifactUpdated is the payload of an artifact_updated room event: an
// artifact changed (metadata only, never content). Reason is "" for a new
// version, "thumbnail" when a version thumbnail was stored.
export interface ArtifactUpdated {
  artifactId: string;
  kind: string;
  title: string;
  mimeType: string;
  fileName: string;
  currentVersion: number;
  updatedBy: string;
  updatedAtMs: number;
  reason?: string;
  // SourceJobID is the agent job whose turn published the new version
  // ("" for a person's own): what caused it, so a scheduled run's own
  // file never triggers its room's tasks (docs/prd/2026-10-21-room-events.md).
  sourceJobId?: string;
}

// ---- wire/assist.go ----

// Assist task outputs (an assist component's manifest "output").
export const AssistOutputText = "text";
export const AssistOutputJSON = "json";

// AssistOutputs are the outputs an assist task may declare.
export const AssistOutputs: readonly string[] = ["text", "json"];

// Context an assist task may receive (its manifest "context"), resolved by
// the server from the ids in the request after checking the caller may
// read them.
export const AssistContextRoom = "room";
export const AssistContextArtifact = "artifact";
export const AssistContextAttachments = "attachments";
// AssistContextLibrary: the experts and skill packs the member can use.
export const AssistContextLibrary = "library";
// AssistContextClock: the current time in the member's timezone.
export const AssistContextClock = "clock";
// AssistContextCapabilities: what the member could use and does not
// here — the components listed to them, the agents they can reach, an
// agent of their own on this device, other members in the room
// (docs/prd/2026-10-20-never-a-dead-end.md §2.2).
export const AssistContextCapabilities = "capabilities";
// AssistContextConversation: the room's conversation, its channels'
// latest messages the member reads, never the people chat
// (docs/prd/2026-10-20-complete-room-capture.md §2.1).
export const AssistContextConversation = "conversation";

// AssistContexts are the contexts an assist task may declare.
export const AssistContexts: readonly string[] = ["room", "artifact", "attachments", "library", "clock", "capabilities", "conversation"];

// Bounds of an assist request. The text holds a room package's every text
// and its instructions for describe-room's check
// (docs/prd/2026-10-20-complete-room-capture.md §2.1).
export const MaxAssistText = 16000;
export const MaxAssistAttachments = 20;

// AssistStatus is GET /v1/assist: whether assists are available to the
// caller (a configured model, and an organization that has not turned
// them off) and the tasks they can run.
export interface AssistStatus {
  available: boolean;
  tasks: AssistTask[];
}

// AssistTask is one runnable task: the component it resolved to, its
// output and, for JSON output, the fields its reply holds.
export interface AssistTask {
  name: string;
  displayName?: string;
  componentId: string;
  output: AssistOutput;
  fields?: AssistField[];
  context?: AssistContext[];
}

// AssistSpec is an assist component's task (its component.json output,
// fields, context and gate), on its Library view.
export interface AssistSpec {
  output: AssistOutput;
  fields?: AssistField[];
  context?: AssistContext[];
  gate?: AssistGate;
}

// AssistGate is an assist's gate (docs/prd/2026-10-20-never-a-dead-end.md
// §2.1): one yes/no question the decision model answers about the context
// the assist reads. A gated run goes on only when the probability of yes
// is at least Threshold (above 0, at most 1).
export interface AssistGate {
  question: string;
  threshold: number;
}

// Why a gated run did not run its assist (AssistSkipped.Reason).
// AssistSkipBelow: the gate's answer was below its threshold, or the
// decision model declined the question.
export const AssistSkipBelow = "below";
// AssistSkipNoGate: no decision model runs for the caller.
export const AssistSkipNoGate = "no-gate";

// AssistSkipped answers a gated run that stopped at its gate: no chat
// model was called.
export interface AssistSkipped {
  skipped: boolean;
  reason: AssistSkipReason;
}

// A JSON task's field shapes (AssistField.Type).
// AssistFieldText is a string (the default).
export const AssistFieldText = "text";
// AssistFieldList is a list of strings (tags).
export const AssistFieldList = "list";
// AssistFieldItems is a list of objects whose fields (Item) are strings.
export const AssistFieldItems = "items";

// AssistFieldTypes are the field shapes a JSON task may declare.
export const AssistFieldTypes: readonly string[] = ["text", "list", "items"];

// MaxAssistItems bounds an items field of a reply.
export const MaxAssistItems = 20;

// AssistField is one field of a JSON task's reply: a string, a list of
// strings, or a list of objects whose own fields (Item, strings only) it
// names.
export interface AssistField {
  name: string;
  description?: string;
  type?: AssistFieldType;
  item?: AssistField[];
}

// AssistRequest is POST /v1/assist/{task}: what the member typed and the
// ids of what it refers to. ChannelID is the room channel the composer is
// in (its recent messages; "" = the room's default channel); ExpertID the
// expert picked for the message (else the room's). An artifact and the
// attachments are the room's, so they need RoomID.
export interface AssistRequest {
  text: string;
  roomId?: string;
  channelId?: string;
  expertId?: string;
  artifactId?: string;
  attachmentIds?: string[];
  // Timezone is the member's IANA timezone (the clock context; UTC when
  // absent or unknown).
  timezone?: string;
  // ReplySeq names an agent reply in the channel (its room sequence):
  // the room context then holds that turn, its request and the reply.
  replySeq?: number;
  // HasOwnAgent is the client's word that the member has an agent of
  // their own on this device (the capabilities context).
  hasOwnAgent?: boolean;
  // SandboxedRun is the client's word that the reply's turn was the
  // member's own agent running in their agent sandbox, which reaches no
  // private host it was not allowed; MayAllowHosts that the sandbox's
  // settings let the member allow one (the capabilities context).
  sandboxedRun?: boolean;
  mayAllowHosts?: boolean;
  // Gated asks the task's gate first (AssistGate): below it, or with no
  // decision model for the caller, the answer is AssistSkipped; a task
  // without a gate refuses it.
  gated?: boolean;
}

// AssistUsage is a call's token counts and latency.
export interface AssistUsage {
  model: string;
  promptTokens: number;
  completionTokens: number;
  latencyMs: number;
}

// AssistDelta is a text task's "delta" event: the next piece of the reply.
export interface AssistDelta {
  text: string;
}

// AssistDone is a text task's "done" event.
export interface AssistDone {
  usage: AssistUsage;
}

// AssistJSONReply is a JSON task's answer: the declared fields only, in
// their shapes (a string, a list of strings, a list of string objects).
export interface AssistJSONReply {
  fields: Record<string, unknown>;
  usage: AssistUsage;
}

// AssistModelConfig is GET /v1/platform/assist-model: the deployment's
// assist model. The key is never returned, only whether one is set.
// Configurable is false without a secret store key (the key is never
// stored in clear).
export interface AssistModelConfig {
  configurable: boolean;
  baseUrl: string;
  model: string;
  keySet: boolean;
  // OrgHosts are the hosts an organization's own model may use (platform
  // model only; none = organizations cannot set their own).
  orgHosts?: string[];
  updatedBy?: string;
  updatedAtMs?: number;
}

// AssistModelUpdate is PUT /v1/platform/assist-model (and, without
// OrgHosts, PUT /v1/tenant/assist-model). An empty APIKey keeps the
// stored key; ClearKey removes it. An empty BaseURL turns the model off
// (an organization's: back to the platform's).
export interface AssistModelUpdate {
  baseUrl: string;
  model: string;
  apiKey?: string;
  clearKey?: boolean;
  orgHosts?: string[];
}

// AssistOrgModel is GET /v1/tenant/assist-model: the organization's own
// model (Model.BaseURL "" = it uses the platform's) and the hosts it may
// name.
export interface AssistOrgModel {
  model: AssistModelConfig;
  // AllowedHosts are the platform's OrgHosts; empty = an organization
  // cannot set its own model.
  allowedHosts: string[];
  // PlatformModel names the platform's model ("" = none), shown as what
  // members use when the organization sets none.
  platformModel?: string;
}

// AssistModelTest is POST /v1/platform/assist-model/test (and
// /v1/tenant/assist-model/test): one short completion through the stored
// model.
export interface AssistModelTest {
  ok: boolean;
  error?: string;
  reply?: string;
  usage: AssistUsage;
}

