// ---- wire/audit_log.go ----

// TruncatedHeader names the response header an audit CSV export sets to
// the row cap when it stopped there (the gateway exposes it to
// cross-origin clients).
export const TruncatedHeader = "X-Bnbloc-Truncated";

// Audit log entry kinds written by the platform itself. Component kinds
// (core, plugin, notifier, auth-provider, share-target, service, webhook) are the extension kinds
// recorded by the component lifecycle and their deliveries.
export const AuditKindBorrow = "borrow";
export const AuditKindSession = "session";
export const AuditKindMember = "member";
export const AuditKindTenant = "tenant";
export const AuditKindAPIToken = "api-token";
export const AuditKindAdminAlert = "admin-alert";
// AuditKindPlatformAgent: the platform-agent policy saved (platform
// level) or a platform agent added to / removed from a room (the room's
// tenant).
export const AuditKindPlatformAgent = "platform-agent";
// AuditKindRetention: a data retention policy saved (platform default or
// a tenant override) or a retention pass deleting a tenant's expired
// data (docs/prd/2026-10-10-enterprise-scale.md §3).
export const AuditKindRetention = "retention";
// AuditKindContent: a content component used for a run (an expert a
// chat asked an agent to wear).
export const AuditKindContent = "content";
// AuditKindApp: an interactive app's data read out (name = the app):
// an owner's export, or an agent's read through its job's grant.
export const AuditKindApp = "app";
// AuditKindRoomSetup: a room's setup an agent changed for the person
// who asked it, through the room tool room_setup (name = the room; the
// detail says what: the description, the welcome, a channel, an expert
// or a pack, a schedule; never its text).
export const AuditKindRoomSetup = "room-setup";
// AuditKindAssist: an AI assist ran (name = task@version; the model,
// tokens and latency, never the text) or the assist model was set.
export const AuditKindAssist = "assist";
// AuditKindSource: a room's consented source (name = the reading
// room): an admin's grant or withdrawal, a schedule's read through
// read_records (the source, the range and the count, never a record).
export const AuditKindSource = "source";
// AuditKindEvent: an event a member sent to a room (name = the room;
// the detail names its type and subject and how many tasks it set,
// never its data).
export const AuditKindEvent = "event";

// AuditLogEntry is one normalized audit record. ID is unique across sources
// ("<source>:<row id>"). Name is the record's subject (component name, member
// id, token id, the borrowed agent's owner, ...). TenantID is empty for a
// platform-level record (only the platform view shows those).
export interface AuditLogEntry {
  id: string;
  source: string;
  kind: string;
  name: string;
  action: string;
  actor?: string;
  tenantId?: string;
  outcome?: string;
  detail?: string;
  roomId?: string;
  atMs: number;
}

// AuditLogReply is one page, newest first. NextCursor is opaque; absent at
// the end of the log.
export interface AuditLogReply {
  entries: AuditLogEntry[];
  nextCursor?: string;
}

// Audit outcomes: the one vocabulary of an audit record's outcome
// (internal/audit.Record writers; the web's auditOutcomeTone reads it).
export const AuditOutcomeOK = "ok";
export const AuditOutcomeAllow = "allow";
export const AuditOutcomeDeny = "deny";
export const AuditOutcomeDelivered = "delivered";
export const AuditOutcomeFailed = "failed";
export const AuditOutcomeQueued = "queued";
export const AuditOutcomeRunning = "running";
export const AuditOutcomeRevoked = "revoked";

// ---- wire/budgets.go ----

// UsageBudgetLimits is one budget as an admin sets it. At least one of Tokens
// / Cost is set; an absent one is no limit on that dimension.
export interface UsageBudgetLimits {
  tokens?: number;
  cost?: number;
  // WarnAtPercent (1..99, default 80) sends the first warning; reaching
  // 100% sends the second.
  warnAtPercent: number;
  // HardStop refuses the member's own agent drives (tenant budget: every
  // drive in the organization) once the budget is reached.
  hardStop: boolean;
}

// MemberBudgetLimits is a member budget in PUT /v1/tenant/budgets.
export interface MemberBudgetLimits extends UsageBudgetLimits {
  userId: string;
}

// TenantBudgetsUpdate is the body of PUT /v1/tenant/budgets: the whole budget
// set (an absent tenant budget or member is removed).
export interface TenantBudgetsUpdate {
  tenant: UsageBudgetLimits | null;
  members: MemberBudgetLimits[];
}

// UsageBurn is the usage measured against a budget in the period.
export interface UsageBurn {
  tokens: number;
  cost: number;
}

// BudgetView is one budget with its burn: Percent is the higher of the
// token and cost burn percentages (floored); Reached when either is at or
// over its limit.
export interface BudgetView extends UsageBudgetLimits {
  userId?: string;
  burn: UsageBurn;
  percent: number;
  reached: boolean;
  updatedBy?: string;
  updatedAtMs?: number;
}

// MemberBurn is one owner's burn in the period (budgeted or not).
export interface MemberBurn extends UsageBurn {
  userId: string;
}

// BudgetPeriod is the month a budget reply covers.
export interface BudgetPeriod {
  period: string; // "YYYY-MM" (UTC)
  periodStartMs: number;
  periodEndMs: number;
}

// TenantBudgetsReply is GET (and the answer to PUT) /v1/tenant/budgets.
export interface TenantBudgetsReply extends BudgetPeriod {
  tenant: BudgetView | null;
  members: BudgetView[];
  // Usage is every owner's burn this period, budgeted or not.
  usage: MemberBurn[];
}

// MyBudgetReply is GET /v1/my/budget: the caller's own budget (nil when none)
// and burn, and whether their agents are stopped by a hard stop.
export interface MyBudgetReply extends BudgetPeriod {
  budget: BudgetView | null;
  burn: UsageBurn;
  // Blocked is true when a hard-stop budget is reached; BlockedBy names it
  // ("member" = the caller's own, "tenant" = the organization's).
  blocked: boolean;
  blockedBy?: string;
}

// ---- wire/client_config.go ----

// ClientConfig is GET /v1/public/client-config: the deployment facts a client
// needs before it signs in. SitesOrigin is the separate origin serving
// every site and its app API (BNBLOC_SITES_ORIGIN, e.g.
// https://sites.bnbloc.example.com), empty when sites are served from the
// gateway's own origin; the desktop shell's site scheme forwards there.
export interface ClientConfig {
  sitesOrigin?: string;
}

// ---- wire/component_settings.go ----

// ComponentSettingField is one declared setting with its state in the scope
// a view shows: a secret's value is never returned (Set says whether one is
// stored).
export interface ComponentSettingField extends ComponentSetting {
  set: boolean;
  value?: string;
}

// ComponentSettingsView answers GET and PUT of
// /v1/platform/components/{name}/settings (platform scope) and
// /v1/tenant/components/{name}/settings (the caller's organization): the
// component's settings of that scope with their state, and the required
// settings of this and the scopes above it that are not set (the component
// needs setup while any is).
export interface ComponentSettingsView {
  kind: string;
  name: string;
  version: string;
  description?: string;
  scope: ComponentSettingScope;
  // Available is false when the gateway has no secret store key: values
  // cannot be stored.
  available: boolean;
  // ReachesMembers: the component runs on members' computers (a plugin,
  // a stdio MCP tool), so these values are sent to them.
  reachesMembers: boolean;
  // Asks: an endpoint component beside the gateway (a notifier, an auth
  // provider) that reads these values itself (GET /v1/component-settings);
  // a change reaches it on its next ask.
  asks: boolean;
  fields: ComponentSettingField[];
  missing: ComponentSetting[];
  updatedBy?: string;
  updatedAtMs?: number;
  // Page is the component's own settings page for this scope, when it
  // declares one: it is shown instead of the one form.
  page?: ComponentSettingsPageFrame;
}

// ComponentSettingsPageFrame is where a component's own settings page
// (ComponentSettingsPage) loads for one scope: the browser's frame base on
// the gateway (a ticket for the caller, this scope and this version
// included; the host appends Entry), and the bundle's pin, by which the
// desktop shell serves the same files itself.
export interface ComponentSettingsPageFrame {
  entry: string;
  bundleSha256: string;
  frameUrl: string;
  frameExpiresAtMs: number;
}

// ComponentSettingsUpdate is a PUT of a scope's values: a key absent is
// left as it is, an empty value clears it (an empty secret keeps the
// stored one), Clear clears keys (a secret too). Values of settings the
// component no longer declares are dropped.
export interface ComponentSettingsUpdate {
  values: Record<string, string>;
  clear?: string[];
}

// ComponentSettingsResolved answers GET
// /v1/components/{name}/settings/resolved: the platform and organization
// values of a component installed for the caller, secrets included, which
// the caller's desktop hands the component when it launches it there. Missing
// are the required settings of those scopes that are not set.
export interface ComponentSettingsResolved {
  values: Record<string, string>;
  missing: string[];
}

// ComponentSettingsPath is where an endpoint component beside the gateway
// (a notifier, an auth provider) asks for its settings: a GET signed with
// its component credential, X-Bnbloc-Component "<kind>/<name>" and
// X-Bnbloc-Signature over "GET /v1/component-settings"
// (docs/architecture/endpoint-components.md).
export const ComponentSettingsPath = "/v1/component-settings";

// EndpointComponentSettings answers GET /v1/component-settings: the stored
// platform values of the calling component (secrets included; a setting
// with no stored value is absent and the component applies its own
// default), each organization's values for the organizations the install
// serves that have stored any, the required settings not set per scope,
// and Version, a hash of the rest: the component applies an answer only
// when it changed.
export interface EndpointComponentSettings {
  kind: string;
  name: string;
  version: string;
  platform: Record<string, string>;
  orgs: Record<string, Record<string, string>>;
  missing: EndpointSettingsMissing;
}

// EndpointSettingsMissing are the required settings without a value: the
// platform's, and each listed organization's own.
export interface EndpointSettingsMissing {
  platform: string[];
  orgs: Record<string, string[]>;
}

// OrgSettingsComponent is one component whose organization settings the
// caller's organization sets (GET /v1/tenant/component-settings), of any
// kind: a member's catalog lists only what runs for members, while an
// endpoint component beside the gateway takes organization settings too.
export interface OrgSettingsComponent {
  kind: string;
  name: string;
  version: string;
  description?: string;
  settings: ComponentSetting[];
  settingsPage?: ComponentSettingsPage;
  settingsMissing: string[];
}

// OrgSettingsComponentsReply answers GET /v1/tenant/component-settings.
export interface OrgSettingsComponentsReply {
  components: OrgSettingsComponent[];
}

// The settings of a sandbox component the platform reads by key
// (docs/prd/2026-10-21-sandbox-private-hosts.md): a sandbox package
// declares them in its own `settings` in the shapes pkgmeta holds it to
// (core/pkgmeta/sandbox_settings.go), and they are set in Components.
// SandboxSettingMode (member, choice off|borrowed|all): which of the
// member's agent runs execute their commands in the VM.
export const SandboxSettingMode = "mode";
// SandboxSettingForwardEnv (member, lines): environment variable names
// or PREFIX* patterns let into the member's own sandboxed runs.
export const SandboxSettingForwardEnv = "forwardEnv";
// SandboxSettingPrivateHosts (member, lines): private hosts the
// member's own sandboxed runs reach (an agent reply's card adds one).
export const SandboxSettingPrivateHosts = "privateHosts";
// SandboxSettingOrgHosts (org, lines): private hosts the organization
// opens to every member's own sandboxed runs.
export const SandboxSettingOrgHosts = "orgHosts";
// SandboxSettingMemberHosts (org, choice ask|off): whether a member may
// allow a private host of their own.
export const SandboxSettingMemberHosts = "memberHosts";

// ---- wire/component_shapes.go ----

// ComponentEndpoint is part of a component package (core/pkgmeta).
export interface ComponentEndpoint {
  baseUrl: string;
}

// ComponentArtifact is part of a component package (core/pkgmeta).
export interface ComponentArtifact {
  url: string;
  sha256: string;
}

// ComponentPermissions is part of a component package (core/pkgmeta).
export interface ComponentPermissions {
  network?: string[];
  // Host lists the desktop plugin host API capabilities a plugin sidecar
  // may use (plugin packages only; PluginHostPermissions is the registry).
  // A plugin declaring any gets BNBLOC_PLUGIN_HOST_URL/_TOKEN at launch.
  host?: string[];
}

// ComponentSetting is one setting a component declares in its manifest
// (pkgmeta.Setting; docs/prd/2026-10-19-component-settings.md): what it
// holds (Type), who sets it and for whom (Scope), and how its value
// reaches the component (Deliver; every value is also in the component's
// settings file). Every value is text: a number in decimal, a boolean
// "true" or "false". core/pkgmeta validates a declaration and a value.
export interface ComponentSetting {
  key: string;
  label: string;
  help?: string;
  type: ComponentSettingType;
  scope: ComponentSettingScope;
  // Required: the component does not run until it is set ("needs setup").
  required?: boolean;
  // Default is the value used while none is set (never a secret's).
  default?: string;
  // Options are a choice's values.
  options?: string[];
  deliver?: ComponentSettingDeliver;
}

// ComponentSettingDeliver says how a setting's value reaches the component
// beyond its settings file: an environment variable of its process, or a
// request header of an http MCP tool (a named header, or Authorization:
// Bearer <value>).
export interface ComponentSettingDeliver {
  env?: string;
  header?: string;
  bearer?: boolean;
}

// ComponentSettingsPage is part of a component package (core/pkgmeta): the
// component's own settings page (docs/prd/2026-10-19-component-settings.md
// §2.2a), an HTML file (Entry) of a static bundle the platform shows in a
// sandboxed frame where the one settings form would be. The bundle is an
// archive in the previewer bundle format, pinned here (a gateway artifact's
// url and sha256) rather than in the package's artifacts, which are a
// plugin's or a stdio tool's per-platform binaries (an http tool has none).
export interface ComponentSettingsPage {
  entry: string;
  bundle: ComponentArtifact;
}

// The types of a setting (ComponentSetting.Type). A secret is write-only:
// never shown back, only "set". A path is a path on the member's own
// machine (member scope only). Lines is a list of text lines (folders,
// name patterns, names): stored and sent between the platform's pieces as
// its lines joined by "\n" (so is a deliver.env value), and handed to the
// component as a JSON array of strings in its settings file and on its
// settings page.
export const SettingText = "text";
export const SettingSecret = "secret";
export const SettingURL = "url";
export const SettingNumber = "number";
export const SettingBoolean = "boolean";
export const SettingChoice = "choice";
export const SettingPath = "path";
export const SettingLines = "lines";

// Who sets a setting, and for whom it holds (ComponentSetting.Scope): the
// super admin for the deployment, an organization admin for their
// organization, each member for themselves.
export const SettingScopePlatform = "platform";
export const SettingScopeOrg = "org";
export const SettingScopeMember = "member";

// ComponentSidecar is part of a component package (core/pkgmeta).
export interface ComponentSidecar {
  listenEnv?: string;
  // SupervisedEnv names the env var the desktop sets to "1" at launch so the
  // sidecar knows it is supervised and exits when its stdin pipe closes.
  supervisedEnv?: string;
  localUrl: string;
  args?: string[];
  // TokenEnv names the env var the desktop sets to a fresh random bearer
  // token at every launch. A sidecar declaring it must require that bearer
  // on every request; the desktop hands the same token to its local callers.
  tokenEnv?: string;
  // DataDirEnv names the env var the desktop sets to a per-component
  // private data directory it creates (owner-only) before launch.
  dataDirEnv?: string;
  // MountsEnv names the env var the desktop sets to the descriptor file a
  // plugin with the "sandbox-mounts" capability writes its read-only sandbox
  // mounts to (docs/architecture/sandbox-mounts.md); MountRootEnv the folder
  // the host side of those mounts must be under. Both only with that
  // capability.
  mountsEnv?: string;
  mountRootEnv?: string;
  // Files are extra per-platform artifacts the sidecar needs beside its
  // executable (e.g. a VMM helper binary and a firmware library). Each is
  // published in Package.Artifacts under "<platform>/<name>", downloaded
  // and sha256-verified by the desktop exactly like the executable, and its
  // local path is handed to the sidecar in env Env.
  files?: ComponentSidecarFile[];
}

// ComponentSidecarFile declares one extra sidecar artifact (ComponentSidecar.Files).
export interface ComponentSidecarFile {
  name: string;
  env: string;
  // Executable marks a file the desktop must mark executable (+x).
  executable?: boolean;
}

// ComponentGuest is a sandbox package's machine profile (pkgmeta.Package.Guest).
export interface ComponentGuest {
  // Image is the OCI reference the machine boots (never a host path).
  image: string;
  cpus?: number;
  memoryMiB?: number;
}

// ComponentPreviewer is a previewer package's payload (pkgmeta.Package.Previewer).
export interface ComponentPreviewer {
  // Entry is the bundle-relative HTML document the frame loads.
  entry: string;
  match: FileMatch;
  // Rank orders previewers matching a file with equal specificity, like
  // the web registry's built-ins (lower first).
  rank: number;
  capabilities?: string[];
  toolbar?: ComponentPreviewerToolbarItem[];
}

// FileMatch declares the files something applies to: the files a
// previewer renders, the files a prompt-pack prompt is for. One validator:
// internal/filematch.
export interface FileMatch {
  mimeTypes?: string[];
  extensions?: string[];
}

// ComponentPreviewerToolbarItem is one declared toolbar control; the host renders it
// with its own icon for Icon (a code-owned name).
export interface ComponentPreviewerToolbarItem {
  id: string;
  icon: string;
  label: string;
  kind: string;
}

// ComponentMCP is an MCP component's payload (pkgmeta.Package.MCP).
export interface ComponentMCP {
  // Tools are the tools the server offers, for display (the server's own
  // tools/list stays authoritative at run time).
  tools: ComponentMCPTool[];
  // Credentials is "room" (the room the agent works in is the
  // credential: the bridge gives a stdio server the room relay) or empty.
  // Everything else a server needs is a setting (Package.Settings).
  credentials?: string;
  stdio?: ComponentMCPStdio;
  http?: ComponentMCPHTTP;
}

// ComponentMCPTool is one tool of the server.
export interface ComponentMCPTool {
  name: string;
  description?: string;
}

// ComponentMCPStdio is how a stdio server is started: the materialized binary with
// these arguments (setting values arrive as its process environment and
// settings file).
export interface ComponentMCPStdio {
  args?: string[];
  // Placement is where the server runs: "agent" (or empty) as a child of
  // the agent CLI, "host" as a host process of the bridge that the agent
  // reaches only as an MCP server (docs/prd/2026-10-22-host-run-mcp-tools.md).
  placement?: string;
  // PrivatePaths (placement "host" only) are what the server keeps its
  // state in, relative to the user's config directory: a core that
  // confines its agent CLI denies reading them.
  privatePaths?: string[];
}

// Where a stdio MCP server runs (ComponentMCPStdio.Placement).
export const MCPPlacementAgent = "agent";
export const MCPPlacementHost = "host";

// ComponentMCPHTTP is how an endpoint server is called.
export interface ComponentMCPHTTP {
  auth: ComponentMCPHTTPAuth;
}

// ComponentMCPHTTPAuth is the credential an endpoint server expects: none,
// a bearer token (Authorization: Bearer <the Setting's value>), a named
// header (<Header>: <the Setting's value>), or a member's OAuth sign-in
// (Authorization: Bearer <their access token>).
export interface ComponentMCPHTTPAuth {
  scheme: string;
  header?: string;
  // Setting is the key of the setting carrying a bearer or header
  // scheme's value.
  setting?: string;
  // ClientID (oauth, optional) is a client the publisher registered with
  // the server's authorization server; without it the desktop registers
  // itself where the authorization server allows it.
  clientId?: string;
  // Scopes (oauth, optional) are requested when the server's challenge
  // names none.
  scopes?: string[];
}

// ---- wire/components.go ----

// ComponentProtocolRange is the Core Protocol range a core or sandbox
// package was published for (core/protocol.ProtocolRange).
export interface ComponentProtocolRange {
  min: string;
  max: string;
}

// ComponentTrust is how an installed component was verified: the publisher
// key that signed it and the hash of the package it installed.
export interface ComponentTrust {
  keyId?: string;
  contentHash?: string;
  signed: boolean;
}

// ComponentAdoption counts the members who opted in to a component.
export interface ComponentAdoption {
  memberInstalls: number;
  totalMembers?: number;
}

// PlatformComponent is one installed component in the platform console
// (GET /v1/platform/components).
export interface PlatformComponent {
  kind: string;
  name: string;
  version: string;
  publisher: string;
  runtime: ComponentRuntime;
  contract?: string;
  protocol: ComponentProtocolRange;
  keyId: string;
  contentHash: string;
  installedAtMs: number;
  description?: string;
  capabilities?: string[];
  permissions: ComponentPermissions;
  hooks?: string[];
  settings?: ComponentSetting[];
  // SettingsMissing are the keys of the required platform-scope settings
  // that hold no value (what a super admin still has to set; the platform
  // console's "needs setup"). Organization and member scopes are their
  // owners' to set and are not counted here.
  settingsMissing?: string[];
  settingsPage?: ComponentSettingsPage;
  artifacts?: Record<string, ComponentArtifact>;
  endpoint?: ComponentEndpoint;
  sidecar?: ComponentSidecar;
  // RequiresDesktop marks a component that runs on each member's desktop
  // (a sidecar other than an auth provider, a stdio MCP server).
  requiresDesktop?: boolean;
  // Manifest is a manifest core's interpreted manifest
  // (core/manifestcore.Manifest), shown as published.
  manifest?: unknown;
  previewer?: ComponentPreviewer;
  mcp?: ComponentMCP;
  rollout: ComponentRollout;
  trust: ComponentTrust;
  adoption: ComponentAdoption;
}

// PlatformComponentsReply is GET /v1/platform/components.
export interface PlatformComponentsReply {
  components: PlatformComponent[];
}

// PublishedComponent answers an install: the installed component, and a
// notifier's signing secret on its first install (shown this once).
export interface PublishedComponent extends PlatformComponent {
  secret?: string;
}

// ComponentInstallRequest is POST /v1/platform/components: a package and
// its detached signature, as text.
export interface ComponentInstallRequest {
  package: string;
  signature: string;
  rollout?: ComponentRollout;
}

// ComponentRolloutRequest sets an installed component's rollout.
export interface ComponentRolloutRequest {
  rollout: ComponentRollout;
}

// MemberComponent is one component of the member catalog (GET
// /v1/components): what the member may use, and, once installed for them,
// what their desktop needs to run it.
export interface MemberComponent {
  kind: string;
  name: string;
  version: string;
  publisher?: string;
  description?: string;
  runtime?: ComponentRuntime;
  contract?: string;
  requiresDesktop?: boolean;
  hooks?: string[];
  // Permissions tells the member's desktop how to launch a plugin
  // sidecar: the host API capabilities it may use.
  permissions?: ComponentPermissions;
  // Settings is the component's declaration (docs/prd/2026-10-19-
  // component-settings.md). SettingsSet are the keys of its platform and
  // organization settings that hold a value for the member's
  // organization (values never come here), and SettingsMissing the
  // required ones of those scopes that are not set: while any is, the
  // component needs setup and does not run. Member-scope settings live on
  // the member's desktop. SettingsPage is the component's own settings
  // page, shown instead of the one form.
  settings?: ComponentSetting[];
  settingsSet?: string[];
  settingsMissing?: string[];
  settingsPage?: ComponentSettingsPage;
  artifacts?: Record<string, ComponentArtifact>;
  endpoint?: ComponentEndpoint;
  sidecar?: ComponentSidecar;
  // Capabilities and Protocol tell the desktop/bridge what a protocol
  // component (a sandbox runtime) was published to support before it is
  // launched; the running implementation's discovery stays authoritative.
  capabilities?: string[];
  protocol?: ComponentProtocolRange;
  rollout: ComponentRollout;
  installed: boolean;
  managed: boolean;
  installedAtMs?: number;
  // PublishedAtMs is when the platform installed this version.
  publishedAtMs?: number;
  // MemberInstalls counts the members who opted in (the platform list's
  // adoption.memberInstalls).
  memberInstalls?: number;
  // Guest is a sandbox's machine profile: the desktop prewarms it.
  guest?: ComponentGuest;
  // Previewer is an installed previewer's match/toolbar metadata, its
  // pinned bundle, and the caller's browser frame URL.
  previewer?: MemberComponentPreviewer;
  // MCP is an MCP tool's tools, credentials source and transport.
  mcp?: MemberComponentMCP;
}

// MemberComponentPreviewer is an installed previewer in the member catalog:
// its package payload, its pinned bundle and the caller's frame.
export interface MemberComponentPreviewer extends ComponentPreviewer {
  // BundleURL is the gateway artifact URL of the archive (the desktop
  // downloads it and checks BundleSHA256).
  bundleUrl: string;
  bundleSha256: string;
  // FrameURL is the gateway-relative browser frame base (ticket included);
  // the host appends Entry.
  frameUrl: string;
  frameExpiresAtMs: number;
}

// MemberComponentMCP is an installed MCP tool in the member catalog: its
// package payload and how it is reached.
export interface MemberComponentMCP extends ComponentMCP {
  transport: string;
}

// ComponentsReply is GET /v1/components: the executable catalog the desktop
// supervises and the content components (experts, skill packs) the member
// may use.
export interface ComponentsReply {
  components: MemberComponent[];
  contentComponents: ContentComponent[];
}

// ComponentKey is one trusted publisher key (GET /v1/platform/component-keys).
export interface ComponentKey {
  keyId: string;
  publicKey: string;
  label?: string;
  addedAtMs?: number;
  addedBy?: string;
}

// ComponentKeysReply lists the trusted publisher keys, and whether this
// gateway refuses unsigned packages (the publishing UI demands a signature
// exactly when the install would).
export interface ComponentKeysReply {
  keys: ComponentKey[];
  signatureRequired: boolean;
}

// ---- wire/content_components.go ----

// ContentComponent is one content component as a member sees it, at its
// latest version (or the version a detail names).
export interface ContentComponent {
  id: string;
  kind: ContentKind;
  name: string;
  displayName?: string;
  description?: string;
  category?: string;
  tags?: string[];
  icon?: string;
  owner: string;
  scope: string;
  status: string;
  latestVersion: string;
  // Version is the version the rest of the fields describe (the latest
  // in a listing).
  version: string;
  // Permissions are the declared permissions (scripts, mcp.stdio,
  // mcp.http:<host>); NeedsSandbox is true when they force a sandboxed
  // drive for anyone but the author.
  permissions: string[];
  needsSandbox?: boolean;
  requires: ContentRequires;
  skills?: ContentSkill[];
  quickPrompts?: ContentQuickPrompt[];
  welcome?: string;
  // Prompts are a prompt pack's prompts (content_prompts.go).
  prompts?: ContentPrompt[];
  // EveryRoom is a prompt pack's offer of its starter prompts to every
  // empty room the member opens, not only the rooms it is turned on for
  // (the default starters).
  everyRoom?: boolean;
  // Assist is an assist's task (docs/prd/2026-10-13-ai-assist.md §3).
  assist?: AssistSpec;
  // Mine is true for the caller's own personal component: they author it
  // (new versions, sharing, publishing).
  mine: boolean;
  // Removable is true when the caller may delete it: their own personal
  // component or a shared copy they hold.
  removable: boolean;
  // SharedBy is the author of a shared copy (Owner is its holder).
  sharedBy?: string;
  // SourceID is the author's component a shared copy or an org
  // publication was made from.
  sourceId?: string;
  // SourceLatestVersion is, on a shared copy, the author's latest version
  // when it is newer than the copy's ("update to the author's latest").
  sourceLatestVersion?: string;
  // Publication is, on the caller's own personal component, its
  // organization publication and latest publish request.
  publication?: ContentPublication;
  // Acked is true when the caller confirmed this version's declared
  // permissions (always true for content they authored and for one that
  // declares none).
  acked: boolean;
  // Uses counts the members and rooms that enabled or pinned it.
  uses: number;
  // Runs counts the agent runs that wore an expert and Members their
  // distinct requesters; for a pack, Members counts the members who
  // turned it on for themselves. Each is capped (store.MaxUsageCount).
  runs: number;
  members: number;
  // Favorite is true when the caller starred it; FavoriteCount counts
  // the members of the caller's organization who did (capped like the
  // usage counts).
  favorite: boolean;
  favoriteCount: number;
  // CoverURL is a work's cover image at this version
  // (GET /v1/content-components/{id}/versions/{v}/cover; the session
  // authorizes it; 404 when the work has none, and the card draws the
  // generated cover). Absent for the other kinds.
  coverUrl?: string;
  // WorkType is a work's type at this version (what deliverable it
  // snapshots); WorkFile its one file (absent for a site or an app).
  workType?: WorkType;
  workFile?: string;
  // Recipe is how a work was made (its manifest's), absent when it
  // carries none.
  recipe?: WorkRecipe;
  // Team is a team expert's roster (as its manifest names it).
  team?: ContentTeam;
  // Room is a room package's setup (its channels, schedules, apps and
  // sources); absent for the other kinds.
  room?: RoomSpec;
  createdAtMs: number;
  updatedAtMs: number;
}

// ContentRequires mirrors a manifest's requires (Expert: a room
// package's room expert, "name@range").
export interface ContentRequires {
  expert?: string;
  skills?: string[];
  prompts?: string[];
  mcp?: ContentMCPRequirement[];
  permissions?: string[];
}

// ContentSkill is one skill of a package.
export interface ContentSkill {
  name: string;
  description: string;
}

// ContentQuickPrompt is one expert quick prompt: its text, or Ref
// ("pack/prompt-id") to a prompt of a pack the expert requires, Resolved
// for the viewer when they may use such a pack (nil: the pack is missing).
export interface ContentQuickPrompt {
  title: string;
  prompt: string;
  ref?: string;
  resolved?: ContentPromptRef;
}

// ContentVersion is one immutable version.
export interface ContentVersion {
  version: string;
  sha256: string;
  bundleKey: string;
  // BundleURL is the download path of the bundle (GET /v1/artifacts/…).
  bundleUrl: string;
  sizeBytes: number;
  createdBy: string;
  createdAtMs: number;
}

// ContentComponentDetail answers GET /v1/content-components/{id}.
export interface ContentComponentDetail {
  component: ContentComponent;
  versions: ContentVersion[];
  // Resubmitted is the publish request a new version opened by itself:
  // the organization uses the component (or a request was pending), so
  // the new version waits for an org admin's approval while members keep
  // the approved one ("Gap closure" 5).
  resubmitted?: ContentPublishRequest;
  // OrgPublished is the version a new save published to the
  // organization at once: it uses the component and requires no
  // approval (contentshare.NeedsApproval).
  orgPublished?: string;
  // OrgProposed is the version a save through a job's grant left with
  // its author although the organization uses the component (or a
  // request was pending): a job never takes content to the organization,
  // so it reaches it only when the author publishes it (the room tools
  // put that card in the room).
  orgProposed?: string;
}

// ContentFile is one file of a version: its text when it is UTF-8 and
// small enough to view.
export interface ContentFile {
  path: string;
  sizeBytes: number;
  text?: string;
  binary?: boolean;
}

// ContentVersionDetail answers GET /v1/content-components/{id}/versions/{v}:
// the component as of that version, its instructions (an expert) and its
// files, and each skill's body for the Library form.
export interface ContentVersionDetail {
  component: ContentComponent;
  version: ContentVersion;
  instructions?: string;
  skillBodies?: Record<string, string>;
  files: ContentFile[];
}

// Content use scopes (ContentUse.Scope).
export const ContentUseMember = "member";
export const ContentUseRoom = "room";
// ContentUseRoomExpert is a room's expert: one of its pinned experts
// every agent turn in the room wears (scope id = the room).
export const ContentUseRoomExpert = "room-expert";

// ContentUse is where a component is enabled (a member's skill packs, a
// room's skill packs) or pinned (a room's experts).
export interface ContentUse {
  scope: ContentUseScope;
  scopeId: string;
  componentId: string;
  kind: ContentKind;
  pinnedVersion?: string;
  createdBy: string;
  createdAtMs: number;
  component?: ContentComponent;
  // UpdateAvailable is true when a pinned version is behind the latest.
  updateAvailable?: boolean;
}

// ContentUsesReply answers GET /v1/content-uses?room=: the caller's member
// uses and, with a room, the room's.
export interface ContentUsesReply {
  member: ContentUse[];
  room?: ContentUse[];
  // RoomExpert is the id of the room's expert (one of its pinned
  // experts), when it has one.
  roomExpert?: string;
}

// ContentUseRequest is PUT /v1/content-uses.
export interface ContentUseRequest {
  scope: string;
  roomId?: string;
  componentId: string;
  // Version pins a version; empty follows the latest.
  version?: string;
}

// ChatExpert is the expert a chat asks its agent to wear: a component id
// and an optional version (empty = the latest when the chat is posted;
// the job records the version actually used).
export interface ChatExpert {
  id: string;
  version?: string;
}

// Content sources of an effective package (ContentRef.Source).
export const ContentSourceExpert = "expert";
export const ContentSourceExpertNeeds = "expert-requires";
export const ContentSourceRoom = "room";
export const ContentSourceMember = "member";
export const ContentSourceRoomExpert = "room-expert";

// ContentRef is one resolved package in effect for a turn.
export interface ContentRef {
  componentId: string;
  kind: ContentKind;
  name: string;
  displayName?: string;
  version: string;
  sha256: string;
  bundleKey: string;
  // Owner is the package's author (a shared copy's author, not its
  // holder; "" for platform content): content that is not the agent
  // owner's own and needs the sandbox forces a sandboxed drive.
  owner: string;
  source: string;
  permissions?: string[];
  needsSandbox?: boolean;
  // MCP are the MCP tool components the package requires.
  mcp?: ContentMCPRequirement[];
}

// ContentEffective answers GET /v1/content-components/effective?job=&room=
// for the bridge driving the job: the expert the chat picked and the skill
// packs in effect (room, the agent owner's, the expert's requirements), and
// requirements no usable package satisfies.
export interface ContentEffective {
  expert?: ContentRef;
  // RoomExpert is the room's expert, worn under the chat's own (absent
  // when the room has none, or it is the chat's expert).
  roomExpert?: ContentRef;
  // Team is the chat expert's roster when it is a team, each member's
  // expert resolved as the requester.
  team?: ContentTeam;
  skillPacks: ContentRef[];
  // MCP are the MCP tool components the packages above require that the
  // requester may use (mcp_tools.go).
  mcp?: ContentMCPTool[];
  missing?: string[];
}

// Content scopes on the wire (ContentComponent.Scope, publish requests).
export const ContentScopePersonal = "personal";
export const ContentScopeShared = "shared";
export const ContentScopeOrg = "org";
export const ContentScopePlatform = "platform";

// ContentPublication is an author's view of their component's
// organization publication: the org copy members use (its version and
// status, absent until a first approval) and the latest publish request.
export interface ContentPublication {
  orgComponentId?: string;
  orgVersion?: string;
  orgStatus?: string;
  request?: ContentPublishRequest;
}

// ContentPublishRequest is a request to publish a version of an author's
// component to the organization (status pending, approved, declined or
// withdrawn).
export interface ContentPublishRequest {
  id: string;
  componentId: string;
  kind: ContentKind;
  name: string;
  displayName?: string;
  version: string;
  requestedBy: string;
  note?: string;
  status: string;
  decidedBy?: string;
  decisionNote?: string;
  decidedAtMs?: number;
  createdAtMs: number;
  // ApprovedVersion is the version the organization uses now ("" before
  // a first approval).
  approvedVersion?: string;
}

// ContentShareRequest is POST /v1/content-components/{id}/shares: named
// members of the author's organization and/or a room (its human members),
// at a version (default: the latest), with an optional note for the
// notification.
export interface ContentShareRequest {
  members?: string[];
  roomId?: string;
  version?: string;
  note?: string;
}

// ContentShareReply answers a share: per recipient, the copy and whether it
// was created, moved to the version (updated) or already had it
// (unchanged); recipients skipped with the reason.
export interface ContentShareReply {
  version: string;
  shared: ContentShareResult[];
  skipped: ContentShareSkip[];
  // Room is the room whose share now stands: members who join it later
  // get a copy too, until the author revokes it.
  room?: string;
}

// Share outcomes (ContentShareResult.Status).
export const ContentShareCreated = "created";
export const ContentShareUpdated = "updated";
export const ContentShareUnchanged = "unchanged";

// ContentShareResult is one recipient's copy.
export interface ContentShareResult {
  member: string;
  componentId: string;
  version: string;
  status: string;
}

// ContentShareSkip is a recipient a share did not reach.
export interface ContentShareSkip {
  member: string;
  reason: string;
}

// ContentShares answers GET /v1/content-components/{id}/shares: the
// copies made from the author's component and its standing room shares.
export interface ContentShares {
  copies: ContentCopy[];
  rooms: ContentRoomShare[];
}

// ContentRoomShare is a standing share with a room: members who join the
// room get a copy at Version until the author revokes it
// (DELETE /v1/content-components/{id}/shares/rooms/{room}).
export interface ContentRoomShare {
  roomId: string;
  version: string;
  note?: string;
  createdAtMs: number;
  updatedAtMs: number;
}

// ContentCopy is one shared copy of an author's component
// (GET /v1/content-components/{id}/shares).
export interface ContentCopy {
  member: string;
  componentId: string;
  version: string;
  updatedAtMs: number;
}

// ContentPublishInput is POST /v1/content-components/{id}/publish: scope
// "org" opens a publish request for Version (default: the latest);
// "personal" withdraws a pending request and takes the component out of
// the organization; "platform" is refused with what a platform admin does.
export interface ContentPublishInput {
  scope: string;
  version?: string;
  note?: string;
}

// ContentPublishReply answers a publish: the scope now in effect and the
// request it opened (org).
export interface ContentPublishReply {
  scope: string;
  request?: ContentPublishRequest;
  note: string;
}

// ContentDecisionInput approves or declines a publish request.
export interface ContentDecisionInput {
  note?: string;
}

// ContentReview is GET /v1/tenant/content-requests/{id}: what an org admin
// reviews before approving. Component is the requested version (declared
// permissions, requirements with MCP tools, a team's roster, skills);
// ScriptFiles are the files that execute; Previous is the version the
// organization uses now (nil for a first publication) and Files the
// changes from it, file by file (every file is "added" for a first one).
export interface ContentReview {
  request: ContentPublishRequest;
  component: ContentComponent;
  scriptFiles: string[];
  previous?: ContentComponent;
  files: ContentFileChange[];
}

// File changes of a review (ContentFileChange.Change).
export const ContentFileAdded = "added";
export const ContentFileRemoved = "removed";
export const ContentFileChanged = "changed";

// ContentFileChange is one file that differs between two versions: its
// text before and after (bounded; Truncated when a side was cut), or
// Binary.
export interface ContentFileChange {
  path: string;
  change: string;
  binary?: boolean;
  before?: string;
  after?: string;
  truncated?: boolean;
}

// ContentAdminComponent is an organization's or the platform's published
// component as an admin manages it: the component (any status) and its
// author.
export interface ContentAdminComponent {
  component: ContentComponent;
  tenantId?: string;
  // EnabledTenants limits platform content to these organizations
  // (absent = every organization); set with
  // PUT /v1/platform/components/{name}/tenants?kind=.
  enabledTenants?: string[];
}

// ---- wire/content_drafts.go ----

// ContentDraft answers POST /v1/content-drafts?job=&room= (the room tools'
// components try): a staged, unsaved expert or skill pack that a job the staging
// job dispatches may wear until ExpiresAtMs. It is never listed in a
// Library. Dispatch it with DispatchRequest.Draft = ID.
export interface ContentDraft {
  id: string;
  kind: ContentKind;
  name: string;
  displayName?: string;
  version: string;
  expiresAtMs: number;
}

// ---- wire/content_events.go ----

// EventContentUsesChanged is a transient room event: a room's content uses
// (pinned experts, the room expert, room skill and prompt packs) changed.
// Clients refetch GET /v1/content-uses?room= on it, so the composer and the
// room settings follow without reopening the room. Payload:
// ContentUsesChanged.
export const EventContentUsesChanged = "content_uses_changed";

// ContentUsesChanged is the payload of EventContentUsesChanged.
export interface ContentUsesChanged {
  scope: string;
  componentId: string;
}

// EventContentSaved is a transient room event: the room tools saved a
// content component (components save) for the job's requester, in the
// job's room, or the save of a new version sent it to the organization. The
// workshop shows the save from it ("Saved expert …" with "Open in Library"
// and "Try it now") instead of re-listing the Library after every agent
// reply. Payload: ContentSaved; clients act only on their own (Owner).
export const EventContentSaved = "content_saved";

// ContentSaved actions: a save, a publish request to the organization, or
// a publication to it that took effect at once (the organization requires
// no approval).
export const ContentSavedSaved = "saved";
export const ContentSavedSubmitted = "submitted";
export const ContentSavedPublished = "published";

// ContentSaved is the payload of EventContentSaved.
export interface ContentSaved {
  componentId: string;
  kind: ContentKind;
  name: string;
  displayName?: string;
  version: string;
  // Action is saved (a new component or version), submitted (a publish
  // request to the organization, opened by components publish or by the
  // save of a new version of a component the organization uses) or
  // published (the same, where the organization requires no approval).
  action: ContentSavedAction;
  // Created marks a new component (not a new version).
  created?: boolean;
  // Owner is the member it was saved for (the job's requester).
  owner: string;
}

// PublishProposal is what an agent proposes to share for the person who
// asked it (components publish, docs/prd/2026-10-20-room-setup-by-conversation.md
// §2.3): a notice row of kind NoticePublishProposal carries it as
// payload.proposal. Clients show it, as a card with a Publish button, only
// to For (the job's requester); the share happens when they click it (the
// publish route, as them), never from the tool call.
export interface PublishProposal {
  componentId: string;
  kind: ContentKind;
  name: string;
  displayName?: string;
  version: string;
  // Scope is who it would be shared with (ContentScopeOrg).
  scope: string;
  // Note is the agent's note for the organization's admins.
  note?: string;
  for: string;
}

// ---- wire/content_prompts.go ----

// ContentPrompt is one prompt of a prompt pack. Body holds {{name}}
// placeholders, each one of Variables.
export interface ContentPrompt {
  id: string;
  title: string;
  body: string;
  variables?: ContentPromptVariable[];
  tags?: string[];
  // Slash is the composer command that inserts it ("/release-notes").
  slash?: string;
  // Starter offers it among the starter prompts of a room the pack is
  // turned on for.
  starter?: boolean;
  // Files scopes it to matching files: a starter with files is a file
  // suggestion, not a room starter.
  files?: FileMatch;
  // Selection scopes it to selections of these kinds (a selection
  // suggestion).
  selection?: string[];
  // Uses counts its insertions by every member.
  uses: number;
}

// ContentPromptVariable is one {{name}} of a prompt: a text field, or a
// select of Options.
export interface ContentPromptVariable {
  name: string;
  label?: string;
  default?: string;
  options?: string[];
}

// ContentPromptRef is a pack's prompt an expert quick prompt resolved to:
// the pack (component id, name, version in effect) and the prompt.
export interface ContentPromptRef {
  componentId: string;
  pack: string;
  version: string;
  prompt: ContentPrompt;
}

// SavePromptRequest is POST /v1/content-components/prompts: a prompt saved
// into the caller's personal prompt pack (created on the first save).
export interface SavePromptRequest {
  title?: string;
  body: string;
  tags?: string[];
}

// SavePromptReply answers it: the pack at its new version and the saved
// prompt's id.
export interface SavePromptReply {
  component: ContentComponent;
  promptId: string;
  // Created is true when this save created the pack.
  created: boolean;
}

// ---- wire/cores.go ----

// AgentTarget is one agent a core can drive for the caller
// (GET /v1/local-agent/targets). ID is core-qualified ("<core>/<rawid>",
// core.QualifyTargetID); Core names the core for grouping. The model and
// reasoning pickers are what the core discovered (absent: no picker).
export interface AgentTarget extends AgentModelOptions {
  id: string;
  provider: string;
  core: string;
}

// AgentTargetsReply is GET /v1/local-agent/targets.
export interface AgentTargetsReply {
  targets: AgentTarget[];
}

// Core is one registered core as GET /v1/cores lists it to a member (the
// rollout gate applied). Available means the gateway resolved an endpoint
// for it; Runtime "sidecar" cores are driven by the member's own bridge.
export interface Core {
  name: string;
  available: boolean;
  backend: string;
  runtime?: string;
  requiresDesktop?: boolean;
  rollout?: string;
}

// CoresReply is GET /v1/cores.
export interface CoresReply {
  cores: Core[];
}

// ---- wire/decisions.go ----

// Decision question types.
// DecisionPredicate: a yes/no question; the answer is the probability
// of yes.
export const DecisionPredicate = "predicate";
// DecisionChoice: one of Choices; the answer is the choice, its
// confidence and a probability per choice.
export const DecisionChoice = "choice";
// DecisionScore: a level of Levels (lowest first); the answer is a level
// index (fractional), its confidence and a probability per level.
export const DecisionScore = "score";

// DecisionRefusal is an answer's type when the model declined that one
// question (its other answers stand).
export const DecisionRefusal = "refusal";

// Decision bounds (the provider's own, so a refusal is ours and says why).
export const MaxDecisionQuestions = 128;
export const MaxDecisionLevels = 10;
export const MaxDecisionInputText = 65536;
export const MaxDecisionImages = 8;
export const MaxDecisionImageBytes = 4194304;
export const MaxDecisionInstructions = 4096;
export const MaxDecisionLabel = 512;
export const MaxDecisionDescription = 2048;

// DecisionRequest is POST /v1/decisions: Input (Text, or Messages) and the
// questions. Answers come back in question order.
export interface DecisionRequest {
  // Model is one of the provider's models (the first is the default; an
  // unknown name falls back to it).
  model?: string;
  // Input is the thing to judge: a JSON string, or a list of
  // DecisionMessage (user messages whose parts are input_text /
  // input_image, a data URL). internal/decision.ParseInput reads it.
  input: unknown;
  // Questions are 1…MaxDecisionQuestions questions; names, when set, are
  // unique and come back in the answers.
  questions: DecisionQuestion[];
}

// DecisionMessage is one user message of an input.
export interface DecisionMessage {
  role: string;
  content: DecisionPart[];
}

// DecisionPart is one part of a message: input_text (Text) or input_image
// (ImageURL, a data URL of a PNG, JPEG, WebP or GIF image).
export interface DecisionPart {
  type: string;
  text?: string;
  image_url?: string;
}

// DecisionQuestion is one question.
export interface DecisionQuestion {
  type: DecisionQuestionType;
  name?: string;
  instructions: string;
  // Choices, for a choice question: component.MinDecisionChoices…
  // component.MaxDecisionChoices values.
  choices?: DecisionChoiceOption[];
  // Levels, for a score question: 2…MaxDecisionLevels, lowest first.
  levels?: DecisionLevel[];
}

// DecisionChoiceOption is one value a choice question may answer.
export interface DecisionChoiceOption {
  value: string;
  description?: string;
}

// DecisionLevel is one level of a score question.
export interface DecisionLevel {
  label: string;
  description?: string;
}

// DecisionReply is POST /v1/decisions' answer: one answer per question, in
// question order, and the provider's usage.
export interface DecisionReply {
  // Model is the model the provider says answered.
  model: string;
  answers: DecisionAnswer[];
  usage: DecisionUsage;
}

// DecisionAnswer is one question's answer: its question's type, or
// DecisionRefusal. Probability is a predicate's (the probability of yes);
// Choice a choice's; Score a score's (a level index, possibly fractional).
// Probabilities is per choice value or per level, Confidence the model's
// for the choice or the score.
export interface DecisionAnswer {
  type: string;
  name?: string;
  probability?: number;
  choice?: string;
  score?: number;
  confidence?: number;
  probabilities?: DecisionProbability[];
}

// DecisionProbability is the probability of one choice value (Value, a
// string) or one level (Value, its index, and Label).
export interface DecisionProbability {
  value: unknown;
  label?: string;
  probability: number;
}

// DecisionUsage is the provider's token count for the call (the upstream
// formats' own field names).
export interface DecisionUsage {
  input_tokens: number;
  output_tokens: number;
}

// SystemOneRequest is POST /v1/systemone: State is the thing to judge (a
// string, or any JSON value, judged as its JSON text); Questions is a map
// of question name to SystemOneQuestion, read in its written order
// (internal/decision.FromSystemOne).
export interface SystemOneRequest {
  model?: string;
  state: unknown;
  questions: unknown;
}

// SystemOne question types: SystemOneNoul is the yes/no question (a
// DecisionPredicate); choice and score are named as in the list format.
export const SystemOneNoul = "noul";

// SystemOneReply is POST /v1/systemone's answer: one answer per question,
// keyed by its name.
export interface SystemOneReply {
  model: string;
  answers: Record<string, SystemOneAnswer>;
  usage: DecisionUsage;
}

// SystemOneAnswer is one answer: noul (Noul, the probability of yes),
// choice (Choice, Confidence, Probabilities per label), score (Score,
// Confidence, Legend and Probabilities per level index), or refusal.
export interface SystemOneAnswer {
  type: string;
  noul?: number;
  choice?: string;
  score?: number;
  confidence?: number;
  legend?: Record<string, string>;
  probabilities?: Record<string, number>;
}

// DecisionCapability is GET /v1/decisions: whether decisions run for the
// caller, and the models they may pick from (the first the default).
export interface DecisionCapability {
  available: boolean;
  models?: string[];
}

// ---- wire/dispatch.go ----

// Dispatch guard limits. They are protocol safety constants, not deployment
// data: they bound how far one person's message can fan out through agents
// (at most MaxDispatchFanOut^MaxDispatchDepth jobs), the same for every
// deployment, and the room-tools contract documents them to agents.
// MaxDispatchDepth is the deepest hop a dispatched job may sit at: a
// person's message starts depth 0, each dispatch adds one.
export const MaxDispatchDepth = 3;
// MaxDispatchFanOut is how many jobs one parent job may dispatch
// (persisted dispatches, whatever their outcome).
export const MaxDispatchFanOut = 8;

// DispatchMarker is payload.dispatchedBy on a chat_message an agent
// dispatched: the parent job and its request, the new job's depth and the
// dispatching agent's handle ("jack/codex"). Clients render "maya → via
// jack/codex → bob/claude". An expert the dispatch asked the target to wear is the
// message's ordinary payload.expert.
export interface DispatchMarker {
  jobId: string;
  // ParentSeq is the room sequence of the parent job's request: clients
  // nest the dispatch (and, through its replies' sourceSeq, everything it
  // produced) under that message without looking jobs up.
  parentSeq?: number;
  depth: number;
  via?: string;
  // Role is the team role the dispatch staffs (a team lead's dispatch).
  role?: string;
}

// DispatchRecipient names the agent a dispatch addresses, in the chat
// recipient's shape.
export interface DispatchRecipient {
  ownerId: string;
  provider: string;
  core?: string;
}

// DispatchRequest is the body of POST /v1/rooms/{roomId}/dispatch (and of
// realtime's POST /internal/v1/rooms/{roomId}/dispatch). Expert asks the
// target to wear an expert exactly as a typed chat does (it must be usable
// by the requester, who authors the post). ClientMsgID makes a retried
// dispatch idempotent.
export interface DispatchRequest {
  parentJobId: string;
  recipient: DispatchRecipient;
  text: string;
  expert?: ChatExpert;
  clientMsgId?: string;
  // Role names the team role the dispatch staffs ([a-z0-9-]); the feed
  // labels the dispatch with it.
  role?: string;
  // Draft asks the target to wear a staged draft (ContentDraft.ID, the
  // room tools' components try) instead of an Expert: admitted only for a
  // draft the parent job staged in this room, before it expires.
  draft?: string;
}

// DispatchReply answers an accepted dispatch: the posted message's room
// sequence (deliverables link back to it as sourceSeq) and the new job.
export interface DispatchReply {
  sequence: number;
  jobId: string;
  depth: number;
}

// Dispatch refusal codes: the JSON body of a refused dispatch is
// {"code": <code>, "error": <message>}.
export const DispatchParentNotFound = "parent_not_found";
export const DispatchParentNotRunning = "parent_not_running";
export const DispatchNotParentBridge = "not_parent_bridge";
export const DispatchRequesterGone = "requester_not_member";
export const DispatchDepthExceeded = "depth_exceeded";
export const DispatchFanOutExceeded = "fan_out_exceeded";
export const DispatchSelf = "self_dispatch";
export const DispatchCycle = "dispatch_cycle";
export const DispatchPeopleChat = "people_chat";
export const DispatchExpertUnusable = "expert_not_available";
export const DispatchDraftUnavailable = "draft_not_available";
export const DispatchInvalid = "invalid_dispatch";

// AgentRunDispatch is a run's dispatch origin: the parent job and the hop
// depth (run records of jobs an agent dispatched).
export interface AgentRunDispatch {
  jobId: string;
  depth: number;
}

// ---- wire/event_kinds.go ----

// Room event kinds not declared beside their payloads.
// EventAgentJobCreated carries the queued AgentJob (realtime, PostChat).
export const EventAgentJobCreated = "agent_job_created";
// EventAgentJobUpdated carries the AgentJob after a status change
// (activity).
export const EventAgentJobUpdated = "agent_job_updated";
// EventAgentSessionState carries ReportSessionStateInput (activity): an
// agent session working or idle.
export const EventAgentSessionState = "agent_session_state";
// EventAgentRoster carries {"agents": [...]}: the agents members'
// bridges advertise in the room.
export const EventAgentRoster = "agent_roster";
// EventPresenceJoin / EventPresenceLeave carry {"userId"}; a
// EventPresenceSnapshot follows each with {"members": [...]}.
export const EventPresenceJoin = "presence_join";
export const EventPresenceLeave = "presence_leave";
export const EventPresenceSnapshot = "presence_snapshot";
// EventPresenceTyping carries {"userId"}, scoped to the channel typed in.
export const EventPresenceTyping = "presence_typing";
// EventMessageDeleted / EventMessageEdited carry the message's sequence
// (and the new text), scoped to its channel.
export const EventMessageDeleted = "message_deleted";
export const EventMessageEdited = "message_edited";
// EventArtifactUpdated announces a new artifact version (bnbloc-room).
export const EventArtifactUpdated = "artifact_updated";
// EventArtifactState relays an artifact's live collaboration state.
export const EventArtifactState = "artifact_state";

// EventKindSpec is one registered room event kind.
export interface EventKindSpec {
  // Name is the kind string (wire.Event.Kind).
  name: RoomEventKind;
  // Durable kinds take a per-room sequence and are persisted to the room
  // feed (room_messages): the only kinds history and a handoff package
  // hold. Every other kind is transient, with sequence 0.
  durable?: boolean;
  // Replay kinds are retained in the hub's replay buffer and delivered
  // again to a reconnecting stream. A transient kind is live only: a
  // replayed toast, badge, typing hint or stale state would look new to
  // the client.
  replay?: boolean;
  // Revocation kinds end access to the room (a member removed, the room
  // deleted): the affected streams close after delivering them, and they
  // are never replayed.
  revocation?: boolean;
  // ChannelScoped kinds carry the channelId of the message or channel they
  // concern; a single-channel stream receives them only for its channel.
  channelScoped?: boolean;
  // Preview kinds reach a preview's stream (a person reading a shared room
  // they have not joined, docs/prd/2026-10-22-shared-room-preview.md): the
  // kinds that match what a preview may read over REST, the feed and the
  // deliverables. Every other kind (agent runs and their progress, live
  // views, tasks, rosters, presence, content and app changes) is members'.
  preview?: boolean;
}

// RoomEventKinds is the registry of room event kinds. The web's
// RoomEventKind union (and RoomEventKindValues) is generated from the Name
// of each row: a kind registered here is a kind the web listens for.
export const RoomEventKinds: readonly EventKindSpec[] = [{ name: "chat_message", durable: true, replay: true, channelScoped: true, preview: true }, { name: "agent_messages", durable: true, replay: true, channelScoped: true, preview: true }, { name: "agent_job_created", channelScoped: true }, { name: "agent_job_updated", channelScoped: true }, { name: "agent_job_progress", channelScoped: true }, { name: "job_live_frame", channelScoped: true }, { name: "agent_session_state" }, { name: "agent_roster" }, { name: "presence_join" }, { name: "presence_leave" }, { name: "presence_snapshot" }, { name: "presence_typing", channelScoped: true }, { name: "message_deleted", channelScoped: true, preview: true }, { name: "message_edited", channelScoped: true, preview: true }, { name: "task_updated", channelScoped: true }, { name: "artifact_updated", preview: true }, { name: "artifact_state", preview: true }, { name: "member_joined", preview: true }, { name: "member_removed", revocation: true, preview: true }, { name: "room_deleted", revocation: true, preview: true }, { name: "content_saved" }, { name: "content_uses_changed" }, { name: "app_changed" }];

// ---- wire/events.go ----

// CloudEventsVersion is the CloudEvents spec version every event carries.
export const CloudEventsVersion = "1.0";

// MaxEventDataBytes bounds an event's data (its compact JSON).
export const MaxEventDataBytes = 16384;

// Event sources: who emitted an event (CloudEvent.Source).
// SourcePlatform: the platform itself (a deploy, a publish); the
// gateway records these. A trigger subscribes to it by the same name.
export const SourcePlatform = "bnbloc/platform";
// SourceRoomPrefix + a room id: what happened in that room (a
// file, a member, an app's data); realtime emits these.
export const SourceRoomPrefix = "bnbloc/room/";
// SourceWebhookPrefix + a hook id: what an outside system posted
// to a task's webhook URL (ScheduleHook).
export const SourceWebhookPrefix = "webhook/";
// SourceMemberPrefix + a subject: an event a room's member sent
// to the room (POST /v1/rooms/{roomId}/events: a script, a CI job with
// the member's API token, the CLI's bnbloc events send).
export const SourceMemberPrefix = "bnbloc/member/";

// ReservedEventTypePrefixes are the type prefixes only the platform emits:
// a member's own event (MemberEvent) may not use them, so a task taking
// the platform's or the room's events never runs on a member's imitation.
export const ReservedEventTypePrefixes: readonly string[] = ["platform.", "room.", "component.", "desktop."];

// MemberEvent is the body of POST /v1/rooms/{roomId}/events: what a room's
// member tells the room happened. The server sets the rest of the event
// (source bnbloc/member/<subject>, id, time); the room's tasks whose
// trigger subscribes to SubscribeMember take it.
export interface MemberEvent {
  type: string;
  subject?: string;
  data?: unknown;
}

// MemberEventReply answers a member's event: the event as sent (its id
// and time) and how many of the room's tasks it set to run.
export interface MemberEventReply {
  event: CloudEvent;
  triggered: number;
  dropped?: number;
}

// The sources a task's trigger may subscribe to (ScheduleRecurrence.Source):
// the platform's events, its own room's, what the room's members send it
// (any member: the filter narrows by type and subject), or what is posted
// to its own webhook URL. A subscription never names another room or
// another task's URL: delivery reaches only the tenants and rooms an event
// may reach.
export const SubscribePlatform = "bnbloc/platform";
export const SubscribeRoom = "bnbloc/room";
export const SubscribeMember = "bnbloc/member";
export const SubscribeWebhook = "webhook";

// EventSubscriptionSources is every source a trigger may name, in the order
// an editor shows them.
export const EventSubscriptionSources: readonly string[] = ["bnbloc/platform", "bnbloc/room", "bnbloc/member", "webhook"];

// Platform event types (source SourcePlatform). The gateway records
// each once and hands it to realtime (POST /internal/v1/events).
// PlatformDeployed: the gateway started on a build whose version
// differs from the last one recorded (data: version, previous).
export const PlatformDeployed = "platform.deployed";
// ComponentPublished: a component (any kind) or platform content got a
// new version (subject: its name; data: kind, name, version, rollout).
export const ComponentPublished = "component.published";
// DesktopPublished: a desktop version was activated for the updater
// (data: version, targets).
export const DesktopPublished = "desktop.published";

// PlatformEventTypes is the closed list of platform event types, in the
// order an editor shows them.
export const PlatformEventTypes: readonly string[] = ["platform.deployed", "component.published", "desktop.published"];

// PlatformDeployedData is the data of PlatformDeployed: the build (its
// commit) and the one recorded before it ("" for the first).
export interface PlatformDeployedData {
  version: string;
  previous?: string;
}

// ComponentPublishedData is the data of ComponentPublished (the event's
// subject is the name).
export interface ComponentPublishedData {
  kind: string;
  name: string;
  version: string;
  rollout?: string;
}

// DesktopPublishedData is the data of DesktopPublished: the version and
// the targets the updater has a file for.
export interface DesktopPublishedData {
  version: string;
  targets: string[];
}

// Room event types (source SourceRoomPrefix + the room). realtime
// emits them from the room's own feed and delivers them only to that
// room's tasks.
// RoomFileAdded: a file (artifact) of the room got a version, its first
// or a new one (subject: its file name or title; data: artifactId,
// kind, title, fileName, mimeType, version, by).
export const RoomFileAdded = "room.file.added";
// RoomMemberJoined: a person became a member (subject: their id; data:
// userId).
export const RoomMemberJoined = "room.member.joined";
// RoomAppDataChanged: an interactive app's data changed, coalesced per
// app (subject: the app id; data: appId, collection, changes).
export const RoomAppDataChanged = "room.app.data.changed";

// RoomEventTypes is the closed list of room event types, in the order an
// editor shows them.
export const RoomEventTypes: readonly string[] = ["room.file.added", "room.member.joined", "room.app.data.changed"];

// RoomFileAddedData is the data of RoomFileAdded: the file, the version it
// got and who published it.
export interface RoomFileAddedData {
  artifactId: string;
  kind: string;
  title: string;
  fileName?: string;
  mimeType?: string;
  version: number;
  by: string;
}

// RoomMemberJoinedData is the data of RoomMemberJoined.
export interface RoomMemberJoinedData {
  userId: string;
}

// RoomAppDataChangedData is the data of RoomAppDataChanged: the app, the
// collection of the newest change ("" for a wipe) and how many changes the
// event stands for (writes within one coalescing window are one event).
export interface RoomAppDataChangedData {
  appId: string;
  collection?: string;
  changes: number;
}

// CloudEvent is one event: the CloudEvents 1.0 context attributes and its
// data (JSON, at most MaxEventDataBytes). Data is the emitter's, untrusted:
// a run reads it fenced as data, never as instructions.
export interface CloudEvent {
  specversion: string;
  id: string;
  source: string;
  type: string;
  time: string;
  subject?: string;
  data?: unknown;
}

// EventDispatch is the gateway's hand-off of a platform event to realtime
// (POST /internal/v1/events): the event and the organizations whose tasks
// it reaches (none: every organization; an organization's own component
// publish names only it).
export interface EventDispatch {
  event: CloudEvent;
  tenants?: string[];
  // CauseJob / CauseTenant name the agent job whose grant caused the
  // event (a publish an agent made for its requester), so a scheduled
  // run's own action never triggers its room's tasks; empty for a
  // person's or the platform's own.
  causeJob?: string;
  causeTenant?: string;
}

// EventDispatchReply is realtime's answer to a dispatched event: how many
// tasks it set to run, and how many it dropped over a rate limit.
export interface EventDispatchReply {
  triggered: number;
  dropped?: number;
}

// Webhook subscriptions: a task whose trigger subscribes to SubscribeWebhook
// has its own URL, HookPathPrefix + its hook id, and a secret shown once
// (ScheduleHookSecret). An outside system signs each request with it.
// HookPathPrefix opens a task's webhook URL on the gateway (an open
// route: the signature is the credential).
export const HookPathPrefix = "/v1/hooks/";
// HookSignatureHeader carries "sha256=<hex HMAC-SHA256 of the raw
// body under the hook's secret>". Same header name as a component's
// signed call (NotificationSignatureHeader), a different scheme: an
// outside system signs the body alone, the scheme GitHub uses, so CI
// and repository hosts can call it as they are.
export const HookSignatureHeader = "X-Bnbloc-Signature";
// GitHubSignatureHeader is GitHub's header for the same scheme.
export const GitHubSignatureHeader = "X-Hub-Signature-256";
// HookEventHeader names the event's type; without it (or
// GitHubEventHeader) the JSON body's top-level "type" does.
export const HookEventHeader = "X-Bnbloc-Event";
// GitHubEventHeader is GitHub's event name ("push"); the type becomes
// "com.github.<name>".
export const GitHubEventHeader = "X-GitHub-Event";
// HookDeliveryHeader / GitHubDeliveryHeader name a delivery (the
// event's id); without one the body's "id", else a fresh one.
export const HookDeliveryHeader = "X-Bnbloc-Delivery";
export const GitHubDeliveryHeader = "X-GitHub-Delivery";

// ScheduleHook is a task's webhook URL as the room's members see it: its id
// (the URL is HookPathPrefix + HookID on this deployment) and the refused
// requests; never its secret.
export interface ScheduleHook {
  hookId: string;
  createdAtMs: number;
  // Refused counts requests refused at it (a bad or missing signature,
  // too large, not JSON, no type), LastRefusedAtMs the newest.
  refused?: number;
  lastRefusedAtMs?: number;
}

// ScheduleHookSecret answers creating or rotating a task's webhook
// (POST /v1/rooms/{roomId}/schedules/{scheduleId}/hook): the hook and its
// secret, shown this once.
export interface ScheduleHookSecret {
  hook: ScheduleHook;
  secret: string;
}

// HookReply answers a webhook request: how many tasks it set to run (0 or
// 1: the hook's own task, when its trigger takes the event).
export interface HookReply {
  triggered: number;
}

// ---- wire/handoff.go ----

// RoomExportFormat is the manifest "format" of the only package version this
// build writes and accepts. An import of any other value is refused.
export const RoomExportFormat = "bnbloc.room-export/v1";

// Room feed kinds. Only these two are durable history (RoomEventKinds:
// realtime persists them; presence/typing/state churn is transient), so they
// are the only kinds a handoff package carries.
export const KindChatMessage = "chat_message";
export const KindAgentMessages = "agent_messages";

// RoomExportManifest is manifest.json at the package root.
export interface RoomExportManifest {
  format: string;
  exportedAtMs: number;
  exportedBy: string;
  room: RoomExportRoom;
  // Channels lets an import recreate the room's message streams; messages
  // reference them by the original channel id.
  channels: RoomExportChannel[];
  // Members is informational only: an import never grants anyone access from
  // it, it only offers the list as invite suggestions.
  members: RoomExportMember[];
  agents: RoomExportAgent[];
  // AgentSessions is the platform's view of each agent session the feed
  // carries (ids + attribution + counts) — never core-internal state.
  agentSessions: RoomExportAgentSession[];
  messageCount: number;
  artifactCount: number;
  attachmentCount: number;
}

// RoomExportRoom describes the exported room.
export interface RoomExportRoom {
  id: string;
  name: string;
  topic?: string;
  createdAtMs: number;
}

// RoomExportChannel is one message stream of the exported room. Kind is
// RoomExportChannelPeople for the room's people chat (human-only, never
// visible to agents) and omitted for an ordinary channel; an import restores
// it as the new room's people chat.
export interface RoomExportChannel {
  id: string;
  name: string;
  isDefault: boolean;
  kind?: string;
}

// RoomExportChannelPeople marks the people chat in RoomExportChannel.Kind.
export const RoomExportChannelPeople = "people";

// RoomExportMember is one membership of the exported room.
export interface RoomExportMember {
  userId: string;
  role: string;
}

// RoomExportAgent is one agent that took part in the room, by its room handle
// (owner/provider) and, when the feed recorded it, the core that drove it.
export interface RoomExportAgent {
  owner: string;
  provider: string;
  core: string;
}

// RoomExportAgentSession is one agent session seen in the room feed.
export interface RoomExportAgentSession {
  agentSessionId: string;
  owner?: string;
  provider?: string;
  channelId?: string;
  messageCount: number;
  firstAtMs: number;
  lastAtMs: number;
}

// FeedMessage is one persisted room-feed entry: the room history row shape
// (sequence/kind/payload/atUnixMs/editedAtMs) plus the channel it belongs to.
// It is a messages.jsonl line, a page row of realtime's internal feed read,
// and a row of an import batch.
export interface FeedMessage {
  sequence: number;
  channelId?: string;
  kind: string;
  payload: unknown;
  atUnixMs: number;
  editedAtMs?: number;
}

// FeedPage is one ascending page of realtime's internal feed read.
export interface FeedPage {
  messages: FeedMessage[];
}

// RevisionsPage is GET /v1/rooms/{id}/history/revisions: the room's
// messages edited or deleted after a time, oldest revision first, and the
// room's newest revision time (0 = none). Agents' records follow the room
// with it.
export interface RevisionsPage {
  revisions: MessageRevision[];
  latestMs: number;
  // RetainedFrom is each listed channel's oldest stored message sequence
  // (channel id → seq): data retention purged everything before it, so
  // agents' records drop it too.
  retainedFrom?: Record<string, number>;
}

// MessageRevision is a message's last edit or deletion.
export interface MessageRevision {
  channelId: string;
  sequence: number;
  deleted?: boolean;
  atMs: number;
}

// ImportedMarker is stamped by realtime into payload.imported of every message
// written through the import path, so history readers (the web feed) can mark
// the row as imported. It is server-authored: no client send path can set it.
export interface ImportedMarker {
  fromRoomId: string;
  fromRoomName?: string;
  originalSequence: number;
  importedAtMs: number;
  // EditedAtMs carries the original edit stamp; imported rows are history
  // and cannot be edited again.
  editedAtMs?: number;
}

// Import batch bounds, shared by the room service (which chunks a package's
// messages) and realtime (which enforces them). They bound one internal
// request, not a package: a package is streamed as many batches.
export const MaxImportBatchBytes = 8388608;
export const MaxImportBatchMessages = 500;

// RoomImportBatch is the body of realtime's internal import write: history rows
// to persist (never publish) into the target room, in original order.
export interface RoomImportBatch {
  fromRoomId: string;
  fromRoomName?: string;
  importedAtMs: number;
  messages: FeedMessage[];
}

// RoomImportBatchReply reports how many rows were persisted and the last
// sequence assigned.
export interface RoomImportBatchReply {
  imported: number;
  lastSequence: number;
}

// RoomExportArtifact is artifacts/<artifactId>/artifact.json: the artifact's
// metadata plus every version's metadata and the package path of its content.
export interface RoomExportArtifact {
  artifactId: string;
  channelId?: string;
  kind: string;
  title: string;
  language?: string;
  mimeType?: string;
  fileName?: string;
  currentVersion: number;
  createdBy: string;
  createdAtMs: number;
  updatedAtMs: number;
  versions: RoomExportArtifactVersion[];
}

// RoomExportArtifactVersion is one immutable artifact revision. Storage
// "blob" marks a binary version: its file holds the raw bytes and
// ContentHash is their sha256 (inline text versions: "" or "inline").
// SourceJobID/SourceSeq are provenance in the SOURCE room only; an import
// does not carry them (jobs and sequences are not portable).
export interface RoomExportArtifactVersion {
  version: number;
  contentHash: string;
  storage?: string;
  mimeType?: string;
  sizeBytes?: number;
  sourceJobId?: string;
  sourceSeq?: number;
  summary?: string;
  authorUserId: string;
  createdAtMs: number;
  // File is the package path of this version's content.
  file: string;
}

// RoomExportAttachment is attachments/<attachmentId>/attachment.json.
export interface RoomExportAttachment {
  id: string;
  filename: string;
  contentType: string;
  size: number;
  sha256: string;
  // File is the package path of the attachment bytes.
  file: string;
}

// RoomHandoffInfo is a room's import provenance (GET /v1/rooms/{id}/handoff),
// present only for rooms created by an import.
export interface RoomHandoffInfo {
  roomId: string;
  sourceRoomId: string;
  sourceRoomName: string;
  sourceExportedAtMs: number;
  sourceExportedBy: string;
  importedBy: string;
  importedAtMs: number;
  suggestedMembers: RoomExportMember[];
}

// RoomImportResult answers POST /v1/rooms/import.
export interface RoomImportResult {
  roomId: string;
  name: string;
  importedMessages: number;
  importedArtifacts: number;
  importedAttachments: number;
  // SkippedAttachments lists attachment ids the upload path refused (e.g. a
  // type the current upload policy no longer accepts); their references are
  // dropped from the imported messages.
  skippedAttachments: string[];
  handoff: RoomHandoffInfo;
}

// ---- wire/invites.go ----

// A room's invite code is short enough to read out and type: InviteCodeLen
// characters of InviteCodeAlphabet (31 symbols; no 0, O, 1, I or L, which
// read alike). That is under a million codes, so it is safe only with the
// rest of the policy: a short life, a throttled redemption and codes found
// per tenant (services/room invite policy, docs/prd/2026-10-22-short-invite-
// codes.md). The room service draws codes from this alphabet; the web types
// and normalizes them by it.
export const InviteCodeLen = 4;
export const InviteCodeAlphabet = "ABCDEFGHJKMNPQRSTUVWXYZ23456789";

// ---- wire/job_live.go ----

// EventJobLiveFrame carries JobLiveFrame (realtime), scoped to the job's
// channel: a job has a new frame.
export const EventJobLiveFrame = "job_live_frame";

// MaxLiveInput bounds the input events queued for a job; the oldest are
// dropped past it. The post's own bounds are the tool's contract
// (component.MaxLiveFrameBytes and the rest).
export const MaxLiveInput = 256;

// LiveFrameHeader carries, on the frame image's answer
// (GET .../live/frame), the frame's JobLiveFrame as base64url JSON: a
// viewer opened after the last job_live_frame event knows the view at once.
export const LiveFrameHeader = "X-Bnbloc-Live-Frame";

// LiveFrameIngest is the gateway's hand-off of a post to realtime
// (POST /internal/v1/rooms/{roomId}/live/{jobId}): the frame, and the job's
// facts realtime checks viewers and controllers against.
export interface LiveFrameIngest {
  channelId?: string;
  owner: string;
  requester: string;
  core?: string;
  provider?: string;
  frame: LiveFramePost;
}

// JobLiveFrame is EventJobLiveFrame: a job's newest frame, without the
// image. Owner is whose machine shows it (the only member who may take
// control, until control grants exist); Controller who holds control now.
// Waiting is what a person must do in it before the work goes on (the view
// stays after the turn while it is set), Ready that it looks done; Ended
// says the view closed. Core and Provider are the job's agent (with Owner,
// whom a "continue" message addresses).
export interface JobLiveFrame {
  jobId: string;
  channelId?: string;
  run?: string;
  seq: number;
  width: number;
  height: number;
  title?: string;
  url?: string;
  owner: string;
  core?: string;
  provider?: string;
  controller?: string;
  waiting?: string;
  ready?: boolean;
  ended?: boolean;
  // Dialog is the page's open dialog the controller answers (nil none).
  dialog?: LiveDialog;
  // Crashed: the page crashed in the browser; its owner reloads it.
  crashed?: boolean;
  atMs: number;
}

// JobLiveList is GET /v1/rooms/{roomId}/live: the room's live views now
// (their newest frames' facts), for a viewer that missed their events.
export interface JobLiveList {
  views: JobLiveFrame[];
}

// LiveInputPost is POST /v1/rooms/{roomId}/jobs/{jobId}/live/input: the
// controller's input, in order.
export interface LiveInputPost {
  events: LiveInput[];
}

// LiveControlPost is POST /v1/rooms/{roomId}/jobs/{jobId}/live/control:
// take control (Take) or hand it back. A controller repeats it while in
// control: control lapses LiveControlLapse after the last one, so a closed
// view hands it back by itself.
export interface LiveControlPost {
  take: boolean;
}

// LiveControlReply answers a control post: who holds control now.
export interface LiveControlReply {
  controller?: string;
}

// LiveControlLapseMs is how long control holds without a renewal.
export const LiveControlLapseMs = 15000;

// ---- wire/job_notice.go ----

// JobNotice is one notice row about a job in the room feed: a line that says
// why nothing (or nothing more) came back — a refused or failed drive, a
// swept or budget-refused job, a team member that timed out, a lead's
// progress. It is a synthetic assistant row of an agent_messages batch whose
// payload carries `notice` (its kind): clients render it as a notice, and
// every reader that feeds the room back to an agent skips it (roomlog,
// notify: an agent must never read a notice as something it or another agent
// said). Every writer — the bridge, activity, the room tools — builds its row
// here (Payload, Report), and nothing else sets payload.notice
// (TestNoticesCarryKind).
export interface JobNotice {
  // Kind is payload.notice ("borrow-denied", NoticeProgress, …).
  Kind: string;
  // MessageID is the row's stable message id (idempotent on retry);
  // Kind-Session when empty.
  MessageID: string;
  // JobID and SourceSeq (the room sequence of the message that started
  // the job) let the feed nest the notice under its request.
  JobID: string;
  SourceSeq: number;
  Text: string;
  // Detail is the agent's or its core's own error output, verbatim but
  // cut (a failed turn's failMessage): never bnbloc's sentence and never
  // Markdown. Clients render it fenced (monospace, apart from Text).
  Detail: string;
  // OwnerUserID / Provider attribute the notice to the agent it is about.
  OwnerUserID: string;
  Provider: string;
  // FailReason is the job failure reason the notice reports ("" = none).
  FailReason: string;
  // Extra holds kind-specific fields (e.g. denyReason); it can never
  // override the fields above.
  Extra: Record<string, unknown>;
  // Where the row is recorded (Report). RoomID and ChannelID place it;
  // Session is the activity session it goes under
  // (JobNoticeSessionID(JobID) when empty): never a real agent session,
  // whose reply cursor a notice would move. Seq is its sequence there
  // (JobNoticeSeq when 0: one notice per job, a retry is a replay), and
  // AtUnixMs its creation time.
  RoomID: string;
  ChannelID: string;
  Session: string;
  Seq: number;
  AtUnixMs: number;
}

// Notice kinds written outside the bridge's refusal table (payload.notice).
// NoticeProgress is a team lead's progress line (post_progress).
export const NoticeProgress = "progress";
// NoticeTimeout is a team member that has not answered in time.
export const NoticeTimeout = "member-timeout";
// NoticeJobFailed is a job the server failed (a swept lease, a budget
// refusal at claim).
export const NoticeJobFailed = "job-failed";
// NoticeAttachmentUndelivered names a message's attachments that did not
// reach the agent's workspace, and why (the bridge, once per job, under
// AttachmentNoticeSessionID so the job's own notice still posts).
export const NoticeAttachmentUndelivered = "attachment-undelivered";
// NoticeContextReset says a turn outgrew its model's context window and
// continues in a fresh session (the bridge, at most once per job, under
// ContextResetNoticeSessionID so the job's own notice still posts).
export const NoticeContextReset = "context-reset";
// NoticeFileEdit says the file a request asked to change did not
// change: it never reached the agent (and why), or the agent left it
// as it was (the bridge, once per job, under FileEditNoticeSessionID).
export const NoticeFileEdit = "file-edit";
// NoticeRoomSetup is a change an agent made to the room's setup for
// the person who asked it ("maya's agent set the welcome"; room_setup,
// a line each, under the job's progress session).
export const NoticeRoomSetup = "room-setup";
// NoticePublishProposal asks the person who asked the agent to share a
// component (components publish): payload.proposal is a PublishProposal,
// shown to them only.
export const NoticePublishProposal = "publish-proposal";

// ---- wire/job_progress.go ----

// EventAgentJobProgress carries AgentJobProgress (activity), scoped to the
// job's channel.
export const EventAgentJobProgress = "agent_job_progress";

// Job activity kinds (JobActivity.Kind): Core Protocol's turn activity
// kinds (core/protocol TurnActivity*; core/protocol TestTurnActivityIsTheWires).
// JobActivityTool: a step the agent ran (a command, a file read or
// written, a search).
export const JobActivityTool = "tool";
// JobActivityThinking: the agent is reasoning.
export const JobActivityThinking = "thinking";
// JobActivityText: the agent is writing.
export const JobActivityText = "text";

// Bounds of a job's progress (Core Protocol's MaxTurnActivity and
// MaxTurnActivityTitle; the bridge cuts to them).
export const MaxJobActivity = 8;
export const MaxJobActivityTitle = 120;

// JobActivity is one step of a live job's turn: a short title such as
// "Bash: python extract.py" (never file contents or secrets).
export interface JobActivity {
  kind: JobActivityKind;
  title?: string;
  atMs: number;
}

// AgentJobProgress is EventAgentJobProgress: a live job's turn start and
// latest steps, oldest first (at most MaxJobActivity). AtMs is when the
// bridge read it.
export interface AgentJobProgress {
  jobId: string;
  startedAtMs?: number;
  activity: JobActivity[];
  atMs: number;
}

// JobProgressInput is POST /v1/bridge/jobs/{jobId}/progress: the claiming
// bridge's report of its job's turn.
export interface JobProgressInput {
  bridgeId: string;
  startedAtMs?: number;
  activity: JobActivity[];
}

// ---- wire/limits.go ----

// Limits a service enforces and a client checks before it sends, so the
// client can say why instead of meeting a 4xx. Each is the one value the
// service enforces (and the web reads it from wire.gen.ts): a limit is
// changed here, never in a second copy.
// MaxUnreadRooms bounds one GET /v1/rooms-unread?rooms= query: each
// room costs a membership lookup and a count per channel. A longer list
// is refused (400), never cut, so a client never reads "no unread" into
// a truncated answer.
export const MaxUnreadRooms = 200;
// MaxUnreadSummaryRooms bounds the rooms GET /v1/my/unread looks at: each
// costs one index seek per channel in a single query. A member with more
// rooms gets a floor (UnreadSummary.More), never a cut answer read as exact.
export const MaxUnreadSummaryRooms = 500;
// UnreadSummaryCap is the most rooms with unread messages GET
// /v1/my/unread counts: a switcher shows "99+" beyond it, so the query
// stops there.
export const UnreadSummaryCap = 100;
// MaxAttachmentBytes bounds one chat attachment upload.
export const MaxAttachmentBytes = 26214400;
// MaxBlobBytes bounds one object in the blob store: realtime's blob put,
// so also an artifact version file (BNBLOC_ARTIFACT_MAX_BYTES may only
// lower it) and a super-admin artifact upload at the gateway.
export const MaxBlobBytes = 268435456;
// MaxArtifactStateBytes bounds one live collaboration-state payload. The
// state is transient but fans out to every room subscriber on each
// change, so it stays gesture-sized.
export const MaxArtifactStateBytes = 16384;
// MaxDisplayNameRunes is the longest display name accepted, in
// characters after trimming (Unicode code points, which is also how
// MySQL sizes the VARCHAR(40) column).
export const MaxDisplayNameRunes = 40;
// MaxContentTagRunes bounds one content component tag, in characters.
export const MaxContentTagRunes = 32;
// MaxRoomSourcePurpose bounds a room package's stated purpose for a
// source it asks for (sources[].purpose), in characters.
export const MaxRoomSourcePurpose = 500;
// Media bounds (docs/prd/2026-10-16-voice-and-image-generation.md):
// what one media model call may carry. The gateway enforces them; the
// web reads them here to say why before it sends.
export const MaxMediaAudioBytes = 20971520;
export const MaxMediaTranscriptChars = 32768;
export const MaxMediaPrompt = 4000;
export const MaxMediaImageReplyBytes = 16777216;
export const MaxMediaImageBytes = 12582912;
export const MaxMediaImages = 4;
export const MaxMediaImageInputs = 4;

// ContentTagPattern is the one rule for a content component tag: lower-case
// letters of any script (CJK and other caseless letters included), digits,
// spaces, '_' and '-', starting with a letter or digit. It is valid both as
// Go RE2 and as a JavaScript regular expression with the "u" flag.
export const ContentTagPattern = "^[\\p{Ll}\\p{Lo}\\p{Nd}][\\p{Ll}\\p{Lo}\\p{Nd} _-]*$";

// The safety caps of an interactive app's data (docs/prd/2026-10-12-
// interactive-apps.md §4.5): cost and abuse bounds, not product rules. The
// room service (services/room/appdata.go) enforces them; the app SDK checks
// them before it sends.
// MaxAppDocBytes bounds one document: its JSON body without the server
// stamps.
export const MaxAppDocBytes = 65536;
// MaxAppDocs bounds the documents of one app, all collections together.
export const MaxAppDocs = 100000;
// MaxAppBytes bounds the stored bytes of one app's documents.
export const MaxAppBytes = 268435456;
// MaxAppCollections bounds the named collections of one app.
export const MaxAppCollections = 64;
// MaxAppCollectionNameLen bounds a collection name (letters, digits,
// '_' and '-').
export const MaxAppCollectionNameLen = 64;
// MaxAppDocIDLen bounds a document id (letters, digits, '_', '-', '.'
// and ':').
export const MaxAppDocIDLen = 128;
// MaxAppFindLimit bounds one page of a find.
export const MaxAppFindLimit = 500;
// MaxAppRequestBytes bounds one app data request body: a document plus
// its envelope (AppDocWrite, AppDocPatch).
export const MaxAppRequestBytes = 69632;
// MaxAppFiles and MaxAppFileBytes bound the files one app's pages
// uploaded (app.files), apart from its documents: a form collecting
// photos must not crowd out its own answers. One file is at most
// MaxAttachmentBytes, a chat attachment's cap.
export const MaxAppFiles = 10000;
export const MaxAppFileBytes = 2147483648;
// MaxAppUploadBytes bounds an upload's request body: one file and its
// multipart envelope.
export const MaxAppUploadBytes = 26230784;
// MaxAppAIPrompt and MaxAppAIInput bound an app's ai call, in
// characters: its instruction, and the data it works on (a week of a
// team's logs).
export const MaxAppAIPrompt = 8000;
export const MaxAppAIInput = 60000;
// MaxAppNotifyLogins bounds the logins one app notice names, and
// MaxAppNotifyRecipients the people it reaches (a room's members
// included).
export const MaxAppNotifyLogins = 100;
export const MaxAppNotifyRecipients = 500;

// The caps of a work (docs/prd/2026-10-13-works-gallery-and-make-similar.md):
// contentpkg's work kind enforces them.
// MaxWorkCoverBytes bounds a work's cover image (cover.png, .jpg or
// .webp at the bundle's root, or an image work's image): a larger one
// is not served, and the card draws the generated cover.
export const MaxWorkCoverBytes = 1048576;
// MaxWorkReferences bounds the reference files a work's recipe keeps
// (the request's attachments, in order; the rest are left out).
export const MaxWorkReferences = 8;
// MaxWorkReferenceBytes bounds the reference files of a work together.
export const MaxWorkReferenceBytes = 26214400;

// The bounds of a component's settings (docs/prd/2026-10-19-component-
// settings.md): core/pkgmeta holds a declaration and a value to them; the
// web reads them to say why before it sends.
// MaxComponentSettings bounds the settings one component declares.
export const MaxComponentSettings = 24;
// MaxComponentSettingValueBytes bounds one value (a key, a URL, a
// path: never a document).
export const MaxComponentSettingValueBytes = 4096;
// MaxComponentSettingLines and MaxComponentSettingLineBytes bound a
// lines value (a list of folders, patterns or names): at most this
// many lines, each trimmed, non-empty and at most this long. A lines
// value is held to these instead of MaxComponentSettingValueBytes.
export const MaxComponentSettingLines = 64;
export const MaxComponentSettingLineBytes = 512;

// ---- wire/mcp_tools.go ----

// ContentMCPRequirement is one requires.mcp entry of a package: an MCP tool
// component by name, and the keys of the component's settings the package
// needs set.
export interface ContentMCPRequirement {
  name: string;
  settings?: string[];
}

// RoomRelayRoutes are the gateway routes a room-credential MCP tool reaches
// through the bridge's room relay ("METHOD /path"; pkgmeta.MCPCredentialsRoom):
// each admits a job grant (?room=&job=) and acts as the job's requester. A
// route joins the list only with that admission; the relay refuses the
// rest. A {name} segment matches one path segment (a video's id). The
// relay's own answer about the turn is component.RelaySession.
export const RoomRelayRoutes: readonly string[] = ["POST /v1/decisions", "POST /v1/systemone", "POST /v1/media/image", "POST /v1/media/transcriptions", "POST /v1/media/video", "GET /v1/media/video/{id}", "POST /v1/live"];

// MCP transports of a resolved tool (ContentMCPTool.Transport).
export const MCPTransportStdio = "stdio";
export const MCPTransportHTTP = "http";

// ContentMCPTool is one MCP tool component in effect for a job's turn, as
// the bridge driving it needs it. Values carries the tool's platform and
// organization setting values (secrets included): it is answered only to
// the bridge holding the job's lease and never logged or persisted.
export interface ContentMCPTool {
  name: string;
  version: string;
  transport: string;
  // Artifacts are a stdio server's sha256 pins by platform
  // ("darwin-arm64"): the bridge uses the desktop's materialized binary
  // only when it carries this platform's pin.
  artifacts?: Record<string, string>;
  args?: string[];
  // Placement and PrivatePaths are the stdio server's declaration
  // (ComponentMCPStdio): where it runs and what it keeps private.
  placement?: string;
  privatePaths?: string[];
  // URL and Auth describe an http server.
  url?: string;
  auth?: ComponentMCPHTTPAuth;
  // Settings is the tool's declaration, a setting the content in effect
  // needs marked required.
  settings?: ComponentSetting[];
  // Credentials is "room" when the room is the tool's credential.
  credentials?: string;
  values?: Record<string, string>;
  // RequiredBy are the ids of the packages in effect that require it.
  requiredBy: string[];
}

// ---- wire/media.go ----

// MediaCapabilities is GET /v1/media: which media calls run for the caller
// (a configured provider and an organization that has not turned AI off).
export interface MediaCapabilities {
  transcribe: MediaCapability;
  image: MediaCapability;
  video: MediaCapability;
}

// MediaCapability is one media ability as the caller sees it.
export interface MediaCapability {
  // Available: a provider is configured for the caller's organization.
  available: boolean;
  // Models are the provider's models the caller may pick from (the first
  // the default); empty when the provider serves one.
  models?: string[];
}

// MediaProviderConfig is GET /v1/platform/media/{capability}: the
// capability's providers. The key is never returned, only whether one is
// set. kind names the wire protocol adapter (media.AdapterKind*); auth is
// "key" (a sealed deployment key) or "caller" (each caller's own session
// token is forwarded — a proxy that bills the caller, like the platform's
// own LLM gateway).
export interface MediaProviderConfig {
  configurable: boolean;
  kind: string;
  baseUrl: string;
  model: string;
  // Models are the models a call may name (the provider serves them all);
  // Model is the first of them, the default.
  models?: string[];
  auth: string;
  keySet: boolean;
  // OrgHosts are the hosts an organization's own provider may name (the
  // platform row only; none = organizations cannot set their own).
  orgHosts: string[];
  // Params is the provider's own knobs as the admin set them.
  params?: Record<string, string>;
  updatedBy?: string;
  updatedAtMs?: number;
}

// MediaOrgProvider is GET /v1/tenant/media/{capability}: the organization's
// own provider (BaseURL "" = it uses the platform's) and the hosts it may
// name.
export interface MediaOrgProvider {
  provider: MediaProviderConfig;
  // AllowedHosts are the platform's orgHosts; empty = an organization
  // cannot set its own provider.
  allowedHosts: string[];
  // PlatformModel names the platform's model ("" = none), shown as what
  // members use when the organization sets none.
  platformModel?: string;
}

// MediaProviderUpdate is PUT /v1/platform/media/{capability}: an empty APIKey
// keeps the stored one, ClearKey removes it, an empty BaseURL turns the
// capability off. Kind must name a registered adapter.
export interface MediaProviderUpdate {
  kind: string;
  baseUrl: string;
  model: string;
  // Models are the models a call may name; Model is the first of them.
  models?: string[];
  // Auth is "key" (default: a sealed API key) or "caller" (forward the
  // caller's own session token).
  auth?: string;
  apiKey?: string;
  clearKey?: boolean;
  // OrgHosts is the platform's to set (the hosts organizations may name);
  // an update without it keeps the stored ones.
  orgHosts?: string[];
  params?: Record<string, string>;
}

// MediaProviderTest is POST /v1/platform/media/{capability}/test: one real
// short call through the stored provider.
export interface MediaProviderTest {
  ok: boolean;
  error?: string;
  // Reply is what the provider answered, bounded (a transcript line, or
  // nothing for an image test).
  reply?: string;
  // LatencyMs is the call's wall time.
  latencyMs: number;
}

// MediaTranscribeReply is POST /v1/media/transcriptions: the transcript,
// capped at MaxMediaTranscriptChars characters.
export interface MediaTranscribeReply {
  text: string;
}

// Image aspect ratios a generation may ask for.
export const MediaImageAspectSquare = "square";
export const MediaImageAspectLandscape = "landscape";
export const MediaImageAspectPortrait = "portrait";

// MediaImageAspects are the aspects a generation may ask for.
export const MediaImageAspects: readonly string[] = ["square", "landscape", "portrait"];

// MediaImageRequest is POST /v1/media/image.
export interface MediaImageRequest {
  // Prompt is what to draw, at most MaxMediaPrompt characters.
  prompt: string;
  // Model is one of the provider's models (MediaProviderConfig.Models);
  // the first is the default.
  model?: string;
  // Aspect defaults to MediaImageAspectSquare.
  aspect?: MediaImageAspect;
  // Count is how many images to draw in one provider call (1…MaxMediaImages,
  // default 1): one request's cost, not n.
  count?: number;
  // Image, when set, is the image to change (an edit) instead of drawing a
  // new one: a data URL the caller holds (a previous reply's, an
  // attachment's bytes the caller may read). At most MaxMediaImageBytes.
  image?: string;
  // Publish, when true in a room (an agent's job grant, ?job=&room=, or a
  // room app's page), publishes each drawn image into the room's Docs: the
  // reply carries each image's artifactId. A member's own call (no room)
  // never publishes.
  publish?: boolean;
  // FileName, with Publish, names the first image (poster.png); the rest
  // are numbered (poster-2.png…).
  fileName?: string;
  // ArtifactID, in a room (as Publish), is the room image to edit: it is
  // read as the caller (a job's requester, an app's participant), and the
  // result is published as its next version
  // (docs/prd/2026-10-17-image-generation-redesign.md §2.2).
  artifactId?: string;
  // Region, with an edit, is the part of the image to change, in its own
  // pixels: the provider gets a mask.
  region?: MediaImageRegion;
  // Inputs, in a room, are room files (art_…) and attachments (att_…) the
  // prompt uses as references, at most MaxMediaImageInputs, read as the
  // caller. Without ArtifactID the first is the image to change.
  inputs?: string[];
}

// MediaImageRegion is a rectangle of an image in its own pixels, origin at
// the top-left. With Mask, the area a member painted: Mask is the message's
// mask attachment (att_…, a PNG of the image's size, transparent where it
// may change), which is the edit's mask, and the rectangle is its bounding
// box (docs/prd/2026-10-17-image-generation-redesign.md §2.7).
export interface MediaImageRegion {
  x: number;
  y: number;
  w: number;
  h: number;
  mask?: string;
}

// MediaImageReply is POST /v1/media/image's answer: the images inline
// (dataUrl), never a link out to another host. One answer per Count ask.
export interface MediaImageReply {
  images: MediaImage[];
}

// MediaImage is one generated (or edited) image.
export interface MediaImage {
  dataUrl?: string;
  // ArtifactID, when the call published, is the room artifact the image
  // became (and DataURL is empty: the image is not also inlined); Version
  // its version (above 1 for an edit), FileName its name, and Note what
  // happened when it is not what was asked (an edit saved as a new file).
  artifactId?: string;
  version?: number;
  fileName?: string;
  note?: string;
  mimeType: string;
  width: number;
  height: number;
  // RevisedPrompt is the provider's own rewording, when it sends one: data
  // the provider wrote, fenced wherever an agent reads it.
  revisedPrompt?: string;
}

// Video aspect ratios a generation may ask for (the provider's size: 16:9
// is 1280x720, 9:16 is 720x1280, unless the provider's params say
// otherwise).
export const MediaVideoAspectLandscape = "16:9";
export const MediaVideoAspectPortrait = "9:16";

// MediaVideoAspects are the aspects a video may ask for.
export const MediaVideoAspects: readonly string[] = ["16:9", "9:16"];

// A video's states (MediaVideoReply.Status): rendering until the provider
// answers it done or failed. Both of those are final.
export const MediaVideoRendering = "rendering";
export const MediaVideoDone = "done";
export const MediaVideoFailed = "failed";

// MediaVideoRequest is POST /v1/media/video: one video submitted to the
// provider, answered at once (docs/prd/2026-10-19-video-generation.md §2.2).
export interface MediaVideoRequest {
  // Prompt is what to film, at most MaxMediaPrompt characters.
  prompt: string;
  // Model is one of the provider's models (MediaProviderConfig.Models);
  // the first is the default.
  model?: string;
  // Seconds is the clip's length, passed to the provider as is (the
  // lengths a model takes are the provider's: 4, 6 or 8 for some); 0 =
  // the provider's default.
  seconds?: number;
  // Aspect defaults to MediaVideoAspectLandscape.
  aspect?: MediaVideoAspect;
}

// MediaVideoReply answers POST /v1/media/video and GET
// /v1/media/video/{id}: the video's id (the provider's own: the gateway
// keeps no job, any replica answers for it) and its status. Once done and
// published into the job's room (?publish=true under a job grant), it names
// the room file; a video is never inlined.
export interface MediaVideoReply {
  id: string;
  status: MediaVideoStatus;
  model?: string;
  // Error is the provider's reason for a failed video, bounded.
  error?: string;
  // ArtifactID, FileName and Bytes name the room file a done video became.
  artifactId?: string;
  fileName?: string;
  bytes?: number;
}

// ---- wire/my_agents.go ----

// MyAgent is one agent the caller's own bridge advertises (any room).
// Online is false while the owner disabled it.
export interface MyAgent {
  core: string;
  provider: string;
  targetId: string;
  online: boolean;
  modelOptions?: AgentModelOptions;
}

// MyDesktop is the caller's own desktop app, apart from its agents: Online
// is its bridge connected now (even with no agent core); LastSeenAtMs the
// latest connection, 0 when the app never connected (not installed).
export interface MyDesktop {
  online: boolean;
  lastSeenAtMs: number;
}

// MyAgentsReply is GET /v1/my/agents: the same agent list the member's
// desktop app shows, because both render what their bridge advertises.
export interface MyAgentsReply {
  agents: MyAgent[];
  desktop: MyDesktop;
}

// ---- wire/my_apps.go ----

// MyApp is one app of the listing.
export interface MyApp {
  // AppID is the site artifact's id (the app's data space is keyed by it).
  appId: string;
  name: string;
  roomId: string;
  roomName: string;
  version: number;
  updatedAtMs: number;
  // Producer made the latest version.
  producer: AppProducer;
  // Documents is the app's document count (its owners' stats); 0 when
  // the app holds no data.
  documents: number;
  // Links are the app's share links that work now (not revoked, not
  // expired), newest first.
  links: AppLink[];
}

// AppProducer is who produced a version: an agent (Owner, Provider, Core),
// or a person (Person) for a manual publish; empty when the source job's
// run record is gone.
export interface AppProducer {
  owner?: string;
  provider?: string;
  core?: string;
  person?: string;
}

// AppLink is one working share link of an app.
export interface AppLink {
  shareId: string;
  access: ShareAccess;
  expiresAtMs: number;
  // Version is the pinned version; 0 follows the latest.
  version: number;
}

// MyAppList is GET /v1/my/apps; NextCursor pages on (absent on the last
// page).
export interface MyAppList {
  apps: MyApp[];
  nextCursor?: string;
}

// ---- wire/notifications.go ----

// Notification types carried in NotificationPayload.Type.
export const NotificationMention = "mention";
export const NotificationAgentFinished = "agent_finished";
export const NotificationAgentFailed = "agent_failed";
export const NotificationBorrowRequest = "borrow_request";
// NotificationTest is only sent by a "send test notification" action
// (super-admin or member); it is never produced by room activity.
export const NotificationTest = "test";
// NotificationAdminAlert is an operational alert a super-admin (or an
// unattended job such as the nightly smoke) sends to platform admins
// (POST /v1/platform/alerts). It has no room and is delivered to exactly
// the listed recipients: member preferences, muted rooms and burst
// collapsing do not apply.
export const NotificationAdminAlert = "admin_alert";
// NotificationBudgetWarning tells a member (member budget) or the org
// admins (tenant budget) that this month's usage budget crossed its
// warning threshold or was reached (R12). Room-less and operational,
// like an admin alert: sent once per threshold per month.
export const NotificationBudgetWarning = "budget_warning";
// NotificationContentShared tells a member that an author shared an
// expert, skill pack or prompt pack with them (a copy in their Library).
// Room-less; it links to the Library.
export const NotificationContentShared = "content_shared";
// NotificationContentReview tells an organization's admins that a
// content component waits for their approval, and its author how they
// decided. Room-less; it links to the Organization console or the
// Library.
export const NotificationContentReview = "content_review";
// NotificationAppNotice is a notice an interactive app sent to the
// room's members or to named people of the organization (app.notify):
// its title is the app's, and it links to the app.
export const NotificationAppNotice = "app_notice";
// NotificationRoomReport tells an organization's admins what a member
// could not get done in a room (POST /v1/rooms/{roomId}/report): the
// member's reviewed text, linked to the reply it is about.
export const NotificationRoomReport = "room_report";
// NotificationScheduleNotice tells a room's owner about one of its
// scheduled tasks' event trigger: events a rate limit dropped
// (docs/prd/2026-10-21-room-events.md §2.4). Operational, like a budget
// warning: sent once per task until it is edited, never muted.
export const NotificationScheduleNotice = "schedule_notice";

// AdminAlertRequest is the body of POST /v1/platform/alerts. Recipients
// default to every configured platform super-admin.
export interface AdminAlertRequest {
  title: string;
  text?: string;
  url?: string;
  recipients?: string[];
}

// AdminAlertResponse answers an accepted alert: the event id (the
// notifier's idempotency key), the recipients, and the notifier components
// it was queued for. Delivery is asynchronous through the outbox.
export interface AdminAlertResponse {
  id: string;
  recipients: string[];
  notifiers: string[];
}

// Notification delivery headers.
// NotificationSignatureHeader carries "t=<unix seconds>,v1=<hex>" where
// v1 = HMAC-SHA256(secret, t + "." + body).
export const NotificationSignatureHeader = "X-Bnbloc-Signature";
// NotificationEventIDHeader repeats NotificationPayload.ID so a receiver
// can de-duplicate retries without parsing the body.
export const NotificationEventIDHeader = "X-Bnbloc-Event-Id";

// NotificationPrefs is a member's notification settings
// (GET/PUT /v1/my/notification-prefs). Defaults: every type on, no quiet rooms.
export interface NotificationPrefs {
  mentions: boolean;
  agentFinished: boolean;
  agentFailed: boolean;
  borrowRequests: boolean;
  contentShared: boolean;
  contentReview: boolean;
  appNotices: boolean;
  roomReports: boolean;
  quietRooms: string[];
}

// RoomReportRequest is POST /v1/rooms/{roomId}/report: a member's note to
// the organization's admins of what the room could not do
// (docs/prd/2026-10-20-never-a-dead-end.md §2.2, the "report" fix), the
// text the member reviewed, and the reply it is about (its room sequence
// and channel; 0 links the room).
export interface RoomReportRequest {
  text: string;
  seq?: number;
  channelId?: string;
}

// MaxRoomReportText bounds a room report's text.
export const MaxRoomReportText = 1000;

// RoomReportReply says whether a note to the organization's admins (a room
// report, or a room's ask for a source's consent) was queued for one
// (false: no notifier, push subscription or desktop reaches one, or every
// admin turned room reports off).
export interface RoomReportReply {
  queued: boolean;
}

// NotificationTestResult answers a test send (POST
// /v1/platform/components/{name}/test and POST /v1/my/notifiers/{name}/test).
// Delivered is true when the notifier answered 2xx and reported no failed
// recipient; Results is the notifier's per-recipient report.
export interface NotificationTestResult {
  delivered: boolean;
  status?: number;
  error?: string;
  eventId: string;
  results?: NotificationRecipientResult[];
}

// NotificationRecipient is one recipient of a notification.
export interface NotificationRecipient {
  userId: string;
  // ReplyToken (N1) is present when the notification accepts a reply
  // (NotificationPayload.Reply set): an opaque per-recipient token the
  // notifier sends back with POST /v1/notifier/replies to post the
  // member's answer into the room. Minted per delivery attempt, valid for
  // 7 days (notify.ReplyTokenTTL); never logged.
  replyToken?: string;
}

// NotificationReply (N1) says where a reply to a notification goes: the room
// channel, and — for an agent outcome — the agent the reply is addressed to
// (the same {ownerId, provider, core} recipient the member's request used;
// borrow rules apply when the member drives another member's agent). A nil
// Recipient posts human chat to the room (a mention).
export interface NotificationReply {
  channelId?: string;
  recipient?: NotificationReplyRecipient;
}

// NotificationReplyRecipient is the agent a reply is addressed to.
export interface NotificationReplyRecipient {
  ownerId: string;
  provider: string;
  core?: string;
}

// NotifierRepliesPath is the gateway route a notifier posts replies to.
export const NotifierRepliesPath = "/v1/notifier/replies";

// NotifierReplyRequest is the signed body of POST /v1/notifier/replies.
// IdempotencyKey is the receiving system's id of the reply message: a retry
// with the same key never posts twice. The reply names its token either
// directly (ReplyToken) or (R9) by a reference the notifier registered with
// POST /v1/notifier/reply-refs: Ref is the message the member answered and
// Sender the receiving system's account that answered — it must be the
// account the reference was registered for. Exactly one of the two forms.
export interface NotifierReplyRequest {
  replyToken?: string;
  ref?: string;
  sender?: string;
  text: string;
  idempotencyKey: string;
}

// NotifierReplyRefsPath (R9) is the gateway route a notifier registers reply
// references at.
export const NotifierReplyRefsPath = "/v1/notifier/reply-refs";

// NotifierReplyRefRequest is the signed body of POST /v1/notifier/reply-refs:
// the notifier sent the notification carrying ReplyToken as the receiving
// system's message Ref to the account Recipient (both opaque, at most 128
// characters). A reply quoting Ref from Recipient then resolves to the token
// in bnbloc, so the notifier keeps no state of its own.
export interface NotifierReplyRefRequest {
  replyToken: string;
  ref: string;
  recipient: string;
}

// NotifierReplyResponse answers an accepted reply with the posted message's
// room sequence (the original sequence for an idempotent retry).
export interface NotifierReplyResponse {
  roomId: string;
  sequence: number;
}

// NotificationRecipientResult is a notifier's per-recipient outcome. A failed
// recipient with Retryable=true is re-sent later (same event id, recipients
// narrowed to the retryable failures); a non-retryable failure is final.
export interface NotificationRecipientResult {
  userId: string;
  ok: boolean;
  error?: string;
  retryable?: boolean;
}

// NotificationDeliveryResponse is the optional 2xx body of a notifier.
export interface NotificationDeliveryResponse {
  results: NotificationRecipientResult[];
}

// MemberNotifier is one notifier component as a member sees it
// (GET /v1/my/notifiers).
export interface MemberNotifier {
  name: string;
  description?: string;
  // OptIn is true for an opt-in component; Installed then says whether the
  // member opted in (only opted-in members receive its notifications).
  optIn: boolean;
  installed: boolean;
}

// NotificationPayload is the signed JSON body posted to a notifier
// component (POST {baseUrl}/v1/notifications).
export interface NotificationPayload {
  id: string;
  type: string;
  tenantId: string;
  roomId: string;
  roomName: string;
  recipients: NotificationRecipient[];
  actor: string;
  title: string;
  text: string;
  url?: string;
  atMs: number;
  // Reply (N1) is set when the notification accepts a reply (mention,
  // agent_finished, agent_failed): each recipient then carries a
  // ReplyToken.
  reply?: NotificationReply;
  // Group, when set, addresses the notification to a group chat a room
  // connected through this notifier instead of members: Recipients is
  // empty, GroupAddress is the notifier's own address of the chat (what
  // it reported when the chat was connected). Only a notifier declaring
  // the groups capability receives one.
  group?: string;
  groupAddress?: string;
}

// ---- wire/payloads.go ----

// ChatMessagePayload is the payload of a chat_message event (realtime's
// PostChat writes it; readers ignore fields they do not know).
export interface ChatMessagePayload {
  // UserID is the author.
  userId: string;
  text: string;
  // ClientMsgID echoes the sender's idempotency id.
  clientMsgId?: string;
  // Recipient addresses one member's agent; nil = people only.
  recipient?: ChatRecipientRef;
  attachments?: ChatAttachment[];
  // DispatchedBy marks a task an agent dispatched through the room tools.
  dispatchedBy?: DispatchMarker;
  // Imported marks a row a handoff import wrote.
  imported?: ImportedMarker;
}

// ChatRecipientRef is the agent a chat message addresses.
export interface ChatRecipientRef {
  ownerId: string;
  provider: string;
  core?: string;
}

// FileRef names the room file a chat message is about: a deliverable at a
// version, which the agent edits (docs/prd/2026-10-14-ai-document-editing.md
// rules 2–4). Name is the file's display name, filled by the server.
export interface FileRef {
  artifactId: string;
  version: number;
  name?: string;
  // Selection is the part of the file the member points at (rule 5): the
  // previewer's chip label and the content it names. It reaches the agent
  // as the file's data, never as the member's words.
  selection?: FileSelection;
}

// FileSelection is a previewer's selection (preview.selection): Label
// 1–MaxFileSelectionLabel characters, Detail at most MaxFileSelectionDetail.
export interface FileSelection {
  label: string;
  detail?: string;
  // Kind is what was selected (FileSelectionKinds; "" = not said).
  kind?: string;
  // Keys are the Compare unit keys the selection covers (a slide's, every
  // cell of a range), at most MaxFileSelectionKeys: the change card names
  // edits outside them (docs/prd/2026-10-14-select-edit-review.md rule 5).
  keys?: string[];
  // Mask is an area painted on an image (kind region): a PNG attachment
  // of the room (att_…) the image's size, transparent where it may change
  // (docs/prd/2026-10-17-image-generation-redesign.md §2.7).
  mask?: string;
}

// FileSelectionKinds is the code-owned vocabulary of selection kinds,
// equal to the frame protocol's SELECTION_KINDS (core/pkgmeta's vocabulary
// test compares them). Prompt packs scope selection suggestions by it.
export const FileSelectionKinds: readonly string[] = ["text", "block", "slide", "cells", "region", "time"];

// The selection bounds, equal to the frame protocol's SELECTION_*_LIMIT
// (core/pkgmeta's vocabulary test compares them).
export const MaxFileSelectionLabel = 120;
export const MaxFileSelectionDetail = 2000;
export const MaxFileSelectionKeys = 500;
export const MaxFileSelectionKey = 200;

// ChatAttachment is an attachment a chat message embeds.
export interface ChatAttachment {
  id: string;
  filename: string;
  contentType: string;
  size: number;
}

// AgentMessagesPayload is the payload of an agent_messages event: the batch
// a bridge (or a JobNotice writer) reported (ReportMessagesInput), with each
// message's payload read as an AgentMessageBody.
export interface AgentMessagesPayload {
  workspaceId: string;
  agentSessionId: string;
  channelId?: string;
  messages: AgentMessage[];
}

// AgentMessage is one reported message of an agent_messages batch.
export interface AgentMessage {
  seq: number;
  payload: AgentMessageBody;
  createdAtUnixMs: number;
}

// AgentMessageBody is the read view of one agent message.
export interface AgentMessageBody {
  messageId: string;
  role: string;
  text: string;
  ownerUserId: string;
  provider: string;
  core?: string;
  // Notice is the notice kind of a JobNotice line ("" for the agent's
  // own message).
  notice?: string;
  jobId?: string;
}

// ---- wire/platform_agents.go ----

// PlatformAgentRef names an agent by its core and provider.
export interface PlatformAgentRef {
  core: string;
  provider: string;
}

// PlatformAgentSpec is one agent a host publishes. DefaultModel (optional)
// is the model a platform turn runs with when the chat carried no explicit
// model; members may still pick another.
export interface PlatformAgentSpec {
  core: string;
  provider: string;
  defaultModel?: string;
}

// PlatformAgentHost is one super admin's published agents: their entry in
// the policy. Only that super admin writes it.
export interface PlatformAgentHost {
  hostUserId: string;
  enabled: boolean;
  agents: PlatformAgentSpec[];
}

// PlatformAgentsPolicy is the platform setting `platform_agents` and the
// answer of GET/PUT /v1/platform/platform-agents: one entry per host. PUT
// {enabled, agents} replaces the caller's entry only.
export interface PlatformAgentsPolicy {
  hosts: PlatformAgentHost[];
}

// PublishedHost is one host publishing an agent, with its spec.
export interface PublishedHost {
  HostUserID: string;
  Spec: PlatformAgentSpec;
}

// PublishedAgent is a platform agent and every host publishing it now.
export interface PublishedAgent {
  Ref: PlatformAgentRef;
  Hosts: PublishedHost[];
}

// PlatformAgentHostState is one host of a platform agent as members see it.
// Online: the host's live bridge advertises the agent; TargetID is the
// core-qualified target it advertises (as in GET /v1/my/agents; empty while
// offline); Queued counts the jobs addressed to this host's agent that have
// not started yet (queued or claimed, across organizations); DefaultModel is
// the host's default for the agent ("" = the core's own default).
export interface PlatformAgentHostState {
  hostUserId: string;
  online: boolean;
  queued: number;
  targetId: string;
  defaultModel?: string;
}

// PlatformAgent is one platform agent (core, provider) as members see it,
// with the state of each host serving it. Online is true when any host is.
// In a room's listing Hosts are the hosts that serve the room, and
// AddedBy/AddedAtMs say who added the agent there and when (the earliest
// grant).
export interface PlatformAgent {
  core: string;
  provider: string;
  online: boolean;
  hosts: PlatformAgentHostState[];
  addedBy?: string;
  addedAtMs?: number;
}

// PlatformAgentsReply is GET /v1/platform-agents and
// GET /v1/rooms/{roomId}/platform-agents.
export interface PlatformAgentsReply {
  agents: PlatformAgent[];
}

// ErrPlatformAgentOffline is the 409 error code of a chat addressed to a
// platform agent whose host is not online (no job is created).
export const ErrPlatformAgentOffline = "platform_agent_offline";

// PlatformAgentOfflineReply is that 409 body.
export interface PlatformAgentOfflineReply {
  error: string;
  message: string;
  hostUserId: string;
  core: string;
  provider: string;
}

// PlatformAgentUsageTotals are the platform-agent runs of one period:
// distinct members and rooms, reported tokens (input + output) and cost.
export interface PlatformAgentUsageTotals {
  runs: number;
  members: number;
  rooms: number;
  tokens: number;
  cost: number;
}

// PlatformAgentUsageMember is one member's platform-agent use this month.
export interface PlatformAgentUsageMember {
  memberId: string;
  runs: number;
  tokens: number;
  cost: number;
}

// PlatformAgentUsageRoom is one room's platform-agent use this month.
export interface PlatformAgentUsageRoom {
  roomId: string;
  roomName: string;
  tenantId: string;
  runs: number;
  tokens: number;
  cost: number;
}

// PlatformAgentUsageRun is one platform-agent run. Agent is "core/provider";
// Model is what the core reported (else the requested or default model);
// Cost is what the host's bridge reported (0 when unpriced or unreported).
export interface PlatformAgentUsageRun {
  atMs: number;
  memberId: string;
  roomId: string;
  roomName: string;
  tenantId: string;
  agent: string;
  hostUserId: string;
  model: string;
  cost: number;
}

// PlatformAgentUsageReply is GET /v1/platform/platform-agents/usage (super
// admin): today's and this month's totals (UTC), the top 5 members and rooms
// of the month by runs, and the last 20 runs, newest first, across every
// organization. Truncated: the month's scan hit its row cap.
export interface PlatformAgentUsageReply {
  today: PlatformAgentUsageTotals;
  month: PlatformAgentUsageTotals;
  topMembers: PlatformAgentUsageMember[];
  topRooms: PlatformAgentUsageRoom[];
  recent: PlatformAgentUsageRun[];
  truncated: boolean;
}

// ---- wire/plugins.go ----

// PluginEventKind is the SSE event name of one PluginDelivery frame.
export const PluginEventKind = "plugin_event";

// ComponentsChangedKind is the SSE event name of a ComponentsChanged hint on
// the same member stream: the member's executable component catalog
// (GET /v1/components) changed, so the desktop refreshes it now instead of
// at its next poll. The stream doubles as the member's desktop channel; a
// desktop holds it whenever its sidecar manager runs, with ?plugins=1 only
// while it runs a plugin sidecar (plugin deliveries and notification routing
// consider only those streams).
export const ComponentsChangedKind = "components_changed";

// ComponentsChanged is the body of realtime's internal
// POST /internal/v1/components/changed (the gateway's signal after a catalog
// change, and the hand-off between realtime replicas) and the data of a
// components_changed frame. It is a hint, not the change: the desktop
// re-reads its catalog. TenantID scopes it to the members signed in to one
// organization ("" = every member); Member scopes it to one member (an
// opt-in install or removal).
export interface ComponentsChanged {
  tenantId?: string;
  member?: string;
  atMs: number;
}

// Plugin delivery outcomes a desktop acknowledges (PluginDeliveryAck.Status).
export const PluginDeliveryDelivered = "delivered";
export const PluginDeliveryFailed = "failed";

// PluginEnvelope is what a plugin sidecar receives at POST /events: the hook's
// versioned event name and an immutable copy of the source event payload.
export interface PluginEnvelope {
  event: string;
  version: string;
  tenantId: string;
  roomId: string;
  payload: unknown;
}

// PluginDelivery is one frame of a member's plugin event stream: the delivery
// id to acknowledge, the plugin it targets, and the envelope to post verbatim.
export interface PluginDelivery {
  id: string;
  plugin: string;
  envelope: unknown;
}

// PluginDeliveryAck reports how the desktop's POST /events went.
export interface PluginDeliveryAck {
  status: string;
  detail?: string;
}

// PluginNotification is the payload of a notification.v1 delivery: ONE
// member's notification, sent to that member's own desktop plugin (e.g. a
// personal bot), which delivers it in place of the server notifiers. The
// member's preferences, muted rooms and burst collapsing were already applied.
export interface PluginNotification {
  // ID is the logical event id (the server notifiers' X-Bnbloc-Event-Id):
  // stable across retries, so a plugin can de-duplicate on (id, userId).
  id: string;
  type: string;
  // UserID is the member this notification is for (their bnbloc subject,
  // typically the IdP email).
  userId: string;
  roomId?: string;
  roomName?: string;
  channelId?: string;
  // Seq is the room message the notification is about (0 = none).
  seq?: number;
  actor: string;
  title: string;
  text: string;
  // URL is the web deep link (absent without BNBLOC_PUBLIC_URL).
  url?: string;
  atMs: number;
  // Reply is set when the member may answer: the plugin posts the answer
  // as a normal chat message through the desktop host API
  // (POST {BNBLOC_PLUGIN_HOST_URL}/v1/chat) addressed as here.
  reply?: PluginNotificationReply;
}

// Reply targets of a PluginNotificationReply.
export const PluginReplyToRoom = "room";
export const PluginReplyToAgent = "agent";

// PluginNotificationReply says where an answer goes: the room channel as
// human chat (To "room", a mention), or the agent the member's request
// addressed (To "agent": the chat recipient {ownerId, provider, core};
// borrow rules apply as for any typed message).
export interface PluginNotificationReply {
  roomId: string;
  channelId?: string;
  to: string;
  agent?: NotificationReplyRecipient;
}

// ---- wire/profiles.go ----

// UserProfile is one user's public profile: GET /v1/users/profiles answers
// {profiles: [UserProfile]} for any id, never with more than the display
// name. DisplayName always has the default applied (store.DisplayName).
export interface UserProfile {
  userId: string;
  displayName: string;
}

// MyProfile is the caller's own profile (GET/PUT /v1/my/profile).
// DisplayName has the default applied; IsDefault reports that no name is
// set (so a settings form shows an empty field with the default as hint).
export interface MyProfile {
  userId: string;
  displayName: string;
  isDefault: boolean;
}

// How a member reads a room's conversation (docs/prd/2026-10-21-feed-by-
// request.md): every message in arrival order, or one block per request.
export const FeedLayoutTime = "time";
export const FeedLayoutRequest = "request";

// MemberPreferences is the caller's own reading preferences (GET/PUT
// /v1/my/preferences), stored with their profile so every device follows
// them. FeedLayout defaults to FeedLayoutTime.
export interface MemberPreferences {
  feedLayout: FeedLayout;
}

// ---- wire/retention.go ----

// RetentionKind is one kind of data a retention policy covers.
export type RetentionKind = "messages" | "artifactVersions" | "audit" | "agentJobs";

// Retention kinds.
// RetentionMessages: room messages (chat and agent replies, with their
// message tasks), the activity copy of agent replies, and chat
// attachments, by age.
export const RetentionMessages = "messages";
// RetentionArtifactVersions: artifact versions other than the latest
// (with the share links pinned to them). The latest version is never
// deleted.
export const RetentionArtifactVersions = "artifactVersions";
// RetentionAudit: the audit trails (borrow decisions, component and
// administration events).
export const RetentionAudit = "audit";
// RetentionAgentJobs: agent jobs that finished (replied, failed, timed
// out or cancelled). Queued and running jobs are never deleted.
export const RetentionAgentJobs = "agentJobs";

// RetentionKinds lists every kind, in display order.
export const RetentionKinds: readonly RetentionKind[] = ["messages", "artifactVersions", "audit", "agentJobs"];

// Retention bounds. The minimum is one month because monthly usage budgets
// and the borrow usage reports read the current month's agent replies and
// audit rows; a shorter period would undercount them. They are properties
// of the product (the budget period), not of a deployment.
export const RetentionMinDays = 31;
export const RetentionMaxDays = 36500;

// RetentionLimits tells a client the accepted range of a days value.
export interface RetentionLimits {
  minDays: number;
  maxDays: number;
}

// RetentionPolicy holds the days of each kind. What an unset (null) value
// means depends on the layer:
//
//   - the platform default: null keeps forever (0 is accepted on write and
//     stored as null);
//   - a tenant override: null uses the platform default, 0 keeps forever
//     (overriding a platform default), N deletes after N days.
//
// The effective policy (EffectiveRetention) holds null for keep forever.
export interface RetentionPolicy {
  messagesDays: number | null;
  artifactVersionsDays: number | null;
  auditDays: number | null;
  agentJobsDays: number | null;
}

// RetentionStatus is what the retention worker last did (platform-wide).
export interface RetentionStatus {
  // LastRunAtMs is when the last row-deletion pass finished (0 = never).
  lastRunAtMs: number;
  // LastBlobGCAtMs is when the last blob collection finished (0 = never).
  lastBlobGcAtMs: number;
  // LastDeleted counts what the last pass deleted, by item (room
  // messages, attachments, blobs, ...).
  lastDeleted: Record<string, number>;
}

// PlatformRetentionView is GET/PUT /v1/platform/retention: the platform
// default (null = keep forever), the accepted range and the worker status.
export interface PlatformRetentionView {
  default: RetentionPolicy;
  limits: RetentionLimits;
  status: RetentionStatus;
}

// TenantRetentionView is GET/PUT /v1/tenant/retention: the tenant's override
// (null = use the platform default, 0 = keep forever), the platform default
// it falls back to, the effective result and the accepted range.
export interface TenantRetentionView {
  tenantId: string;
  override: RetentionPolicy;
  default: RetentionPolicy;
  effective: RetentionPolicy;
  limits: RetentionLimits;
}

// ---- wire/room_components.go ----

// RoomPackageSchedule is a scheduled task of a room package: an AI task,
// a notice to the room's members or a request to an agent without the
// agent (Recipient kind "ai", "notice" or "agent"), its text and when it
// recurs. Channel is a channel name of the package ("" the room's default
// channel). Installing creates it disabled, owned by the installer; a
// request waits for the installer to pick one of their agents.
export interface RoomPackageSchedule {
  channel?: string;
  text: string;
  recipient: ScheduleRecipient;
  recurrence: ScheduleRecurrence;
  timezone: string;
}

// Bounds of what a room package carries beyond its setup
// (docs/prd/2026-10-20-complete-room-capture.md §2.2): contentpkg's room
// checks hold a package to them, and the save dialog shows a capture's
// size against them.
// MaxRoomCarryBytes bounds the apps' sites and the files a room
// package carries, together: one site snapshot's cap
// (tarbundle.SiteLimits; a test holds them equal).
export const MaxRoomCarryBytes = 67108864;
// MaxRoomFiles bounds the files a room package carries.
export const MaxRoomFiles = 20;

// RoomAppSnapshot is an app made in a room that its package carries: its
// title and the package folder holding its site ("apps/<name>"), copied
// into the new room as a new site, without its data.
export interface RoomAppSnapshot {
  title: string;
  dir: string;
}

// RoomPackageFile is a room file its package carries: its name in the new
// room, the package path holding it ("files/<name>") and its size.
export interface RoomPackageFile {
  name: string;
  path: string;
  sizeBytes: number;
}

// RoomSpec is a room package's setup on its Library view (the room
// expert, skill packs and prompt packs are its requires). Apps are works
// by "name@range"; AppSnapshots the apps made in the room it carries;
// Files the room files it carries.
export interface RoomSpec {
  channels: string[];
  schedules: RoomPackageSchedule[];
  apps: string[];
  appSnapshots: RoomAppSnapshot[];
  files: RoomPackageFile[];
  sources: RoomSourceAsk[];
}

// RoomDraftPart is a component a room uses, as a draft captured it: its
// id, names, the version in effect and Ref, the "name@^major" a package
// names it by.
export interface RoomDraftPart {
  id: string;
  name: string;
  displayName?: string;
  version: string;
  ref: string;
}

// RoomDraftDeliverable is a deliverable of the room a draft offers to
// carry: an app made in the room (a site: its current version as a site
// snapshot) or a room file (its current version), with its size.
export interface RoomDraftDeliverable {
  artifactId: string;
  title: string;
  fileName?: string;
  mimeType?: string;
  sizeBytes: number;
}

// RoomDraftTool is an MCP tool component the room's runs had (the run
// records' tools): its name and the permission a package requiring it
// declares (mcp.stdio, or mcp.http:<host>).
export interface RoomDraftTool {
  name: string;
  permission: string;
}

// RoomComponentDraft answers GET /v1/rooms/{roomId}/component-draft: what
// "Save as component" captures of a room for its owner or an admin, to be
// reviewed and saved as a room package through the content form. Name is
// a package name proposed from the room's. Sources are the room's own asks
// (each with its purpose, granted or not: a package asks again for the
// room installed from it). MadeApps and Files are what the room made that
// a package can carry, for the saver to tick (a save names the ticked ones
// in its include); Tools are the MCP tools its recent runs had, which a
// package requires. Left says, a line each, what of the room a package
// does not hold.
export interface RoomComponentDraft {
  roomId: string;
  name: string;
  displayName: string;
  description: string;
  welcome: string;
  quickPrompts: RoomQuickPrompt[];
  channels: string[];
  schedules: RoomPackageSchedule[];
  expert?: RoomDraftPart;
  skills: RoomDraftPart[];
  prompts: RoomDraftPart[];
  apps: RoomDraftPart[];
  madeApps: RoomDraftDeliverable[];
  files: RoomDraftDeliverable[];
  tools: RoomDraftTool[];
  sources: RoomSourceAsk[];
  left: string[];
}

// RoomInclude is what a room package's content save takes from the room it
// captures (the save request's "include"): the room, and by artifact id the
// apps made in it and the room files to carry, each read as the saver reads
// it (the room's owner or an admin). The bytes never pass through the
// client.
export interface RoomInclude {
  roomId: string;
  apps?: string[];
  files?: string[];
}

// RoomInstallRequest is POST /v1/content-components/{id}/create-room: the
// version to install (default the latest) and the new room's id (one is
// made when empty), name (default the component's) and visibility
// ("private" by default, or "shared").
export interface RoomInstallRequest {
  version?: string;
  roomId?: string;
  name?: string;
  visibility?: string;
}

// RoomInstallReply is what installing a room package set up: the new room,
// From ("name@version"), its channels, the ids of its schedules (all
// paused) and, of them, the requests to an agent that wait for the
// installer to pick one of their agents (WaitingForAgent: each one's text
// in a line), the room expert, the packs turned on and the apps copied in
// (labels), the expert made from the package's instructions (Instructions,
// its label), the apps made in the source room and the files copied in
// (labels), what was left out and why (Skipped), and what the room asks
// for that nobody granted yet: its sources (each waits for the organization
// admin's consent, room_sources.go) and its MCP tools, of which ToolsToAdd
// are listed to the installer but not added yet (the install dialog offers
// Add). The package's welcome and quick prompts are the new room's own
// (RoomDetail).
export interface RoomInstallReply {
  roomId: string;
  name: string;
  componentId: string;
  from: string;
  channels: string[];
  schedules: string[];
  waitingForAgent: string[];
  expert?: string;
  enabled: string[];
  apps: string[];
  instructions?: string;
  madeApps: string[];
  files: string[];
  skipped: string[];
  sources: RoomSourceAsk[];
  tools: string[];
  toolsToAdd: string[];
}

// ---- wire/room_sources.go ----

// RoomSourceRuns is the organization's agent conversations: request
// and reply text, the agent, the outcome, the room and the time.
export const RoomSourceRuns = "runs";

// RoomSources are the sources a room package may ask for: the one list.
export const RoomSources: readonly string[] = ["runs"];

// RoomSourceAsk is a source a room package asks for (its manifest's
// sources[]): the source and the purpose its tasks read it for, in the
// author's words, shown to the admin who decides.
export interface RoomSourceAsk {
  name: RoomSource;
  purpose: string;
}

// What a grant covers: the rooms whose records the reading room may read.
// RoomSourceScopeAll: every room of the organization.
export const RoomSourceScopeAll = "all";
// RoomSourceScopeOptedIn: only the rooms whose owner opted in.
export const RoomSourceScopeOptedIn = "opted-in";
// RoomSourceScopeNonePrivate: every room but the private ones (invite
// only, store.VisibilityPrivate).
export const RoomSourceScopeNonePrivate = "none-private";

// RoomSourceScopes are the scopes an admin may grant.
export const RoomSourceScopes: readonly string[] = ["all", "opted-in", "none-private"];

// RoomSourceGrant is one room's ask for a source and the organization
// admin's answer, on the console (GET /v1/tenant/room-sources). From is
// the package it was installed from ("name@version"). Scope "" is waiting
// for the admin (never granted, withdrawn, or paused when the room's owner
// changed). Grantee is the person the grant is pinned to (the room's owner
// when it was granted): only their schedules read it. Changed counts the
// grantee's tasks changed since the admin consented to them, until an
// admin acknowledges.
export interface RoomSourceGrant {
  roomId: string;
  roomName: string;
  source: RoomSource;
  purpose: string;
  componentId: string;
  from: string;
  askedBy: string;
  askedAtMs: number;
  scope?: RoomSourceScope;
  grantee?: string;
  decidedBy?: string;
  decidedAtMs?: number;
  changed?: number;
}

// RoomSourceGrantsReply is GET /v1/tenant/room-sources: every ask of the
// organization's rooms, newest first.
export interface RoomSourceGrantsReply {
  grants: RoomSourceGrant[];
}

// RoomSourceTask is one of a grantee's AI tasks in the reading room as the
// admin consented to it: the schedule and its words.
export interface RoomSourceTask {
  scheduleId: string;
  text: string;
}

// RoomSourceDrift is a grantee's AI task created or changed since the
// admin consented: its words then (Before, "" for a new task) and now,
// and the AI explanation the admins were sent (explain-source-use's
// summary and mismatch; empty when no explanation could be made).
export interface RoomSourceDrift {
  scheduleId: string;
  before: string;
  after: string;
  summary?: string;
  mismatch?: string;
  atMs: number;
}

// RoomSourceDetail is GET /v1/tenant/room-sources/{roomId}/{source}: one
// ask with what its admin decides on. Shared: the reading room is shared
// (a grant needs a private room: its members read what it reads). Owner:
// the room's owner, the person a grant is pinned to. Members: the room's
// human members now. Tasks: the owner's AI tasks in the room now (what
// would read). Drift: the grantee's tasks changed since the admin
// consented. ExplainInput: the explain-source-use assist's <text> for the
// ask (its purpose and the tasks, a changed one with its words before).
export interface RoomSourceDetail {
  grant: RoomSourceGrant;
  shared: boolean;
  owner: string;
  members: RoomMember[];
  tasks: RoomSchedule[];
  drift: RoomSourceDrift[];
  explainInput: string;
}

// RoomSourceDecision is PUT /v1/tenant/room-sources/{roomId}/{source}:
// the scope the admin grants and the person it is read by, the room's
// owner as the admin saw them (a grant to someone no longer the owner is
// refused). DELETE withdraws.
export interface RoomSourceDecision {
  scope: RoomSourceScope;
  grantee: string;
}

// RoomSourceAskState is a source the room asks to read and where it
// stands (Scope "" = waiting for the organization admin) and the person
// a grant is pinned to.
export interface RoomSourceAskState {
  source: RoomSource;
  purpose: string;
  scope?: RoomSourceScope;
  grantee?: string;
}

// RoomReviewer is a room that reads this room's records under a grant:
// its name always (members are told which room does) and the person whose
// tasks read, its id only when the caller is a member of it (they may
// open it).
export interface RoomReviewer {
  source: RoomSource;
  roomName: string;
  roomId?: string;
  grantee: string;
}

// RoomSourcesInfo is GET /v1/rooms/{roomId}/sources for a member: what the
// room asks to read and where each ask stands, which rooms read its own
// records (transparency), and the sources its owner opted it in to (for
// grants of scope opted-in).
export interface RoomSourcesInfo {
  asks: RoomSourceAskState[];
  reviewedBy: RoomReviewer[];
  optedIn: RoomSource[];
}

// RoomSourceOptIn is PUT /v1/rooms/{roomId}/sources/{source}/opt-in: the
// room's owner opts its records in to (or out of) grants of scope
// opted-in.
export interface RoomSourceOptIn {
  optedIn: boolean;
}

// ---- wire/rooms.go ----

// RoomSummary is one room of the caller's own room list
// (GET /v1/users/{id}/rooms?detail=1). Role is the caller's role in it.
export interface RoomSummary {
  roomId: string;
  name: string;
  description: string;
  visibility: RoomVisibility;
  syncMode: RoomSyncMode;
  role: RoomRole;
  memberCount: number;
  createdAtMs: number;
}

// RoomsReply is the caller's room list.
export interface RoomsReply {
  rooms: RoomSummary[];
}

// RoomDetail is GET /v1/rooms/{id} for a member (and the answer to a create
// or a PATCH). The caller's role is not part of it: it comes from the member
// list (RoomMembersReply), the one source a role change updates. Welcome
// and QuickPrompts are what an empty room shows every member
// (docs/prd/2026-10-20-room-setup-by-conversation.md §2.1).
export interface RoomDetail {
  roomId: string;
  name: string;
  description: string;
  visibility: RoomVisibility;
  // Previewable: anyone signed in to the room's organization may read the
  // room without joining it (read-only). Independent of Visibility.
  previewable: boolean;
  syncMode: RoomSyncMode;
  createdBy: string;
  createdAtMs: number;
  memberCount: number;
  welcome: string;
  quickPrompts: RoomQuickPrompt[];
}

// RoomQuickPrompt is one quick prompt of a room: a title and the text a
// click puts into the message box (nothing is sent).
export interface RoomQuickPrompt {
  title: string;
  prompt: string;
}

// RoomWelcomeRequest is PATCH /v1/rooms/{id}/welcome (the room's owner or
// an admin): a nil field is left as it is. The bounds are a room
// package's (contentpkg.CheckRoomStart).
export interface RoomWelcomeRequest {
  welcome?: string;
  quickPrompts?: RoomQuickPrompt[];
}

// RoomPreview is GET /v1/rooms/{id} for a non-member of a shared room: just
// enough for a join card. Preview is always true (a private room answers
// 404 to a non-member).
export interface RoomPreview {
  roomId: string;
  name: string;
  description: string;
  visibility: RoomVisibility;
  memberCount: number;
  preview: boolean;
  // Previewable: the room may be read before joining it, so the room view
  // opens read-only; otherwise this card (and a join) is all a non-member
  // sees.
  previewable: boolean;
}

// RoomMember is one membership of a room. AgentHost marks a platform
// agent's host: in the room only so its bridge drives that agent, never a
// person (clients keep it out of people lists).
export interface RoomMember {
  userId: string;
  role: RoomRole;
  agentHost: boolean;
}

// RoomMembersReply is GET /v1/rooms/{id}/members (members only).
export interface RoomMembersReply {
  members: RoomMember[];
}

// PlazaRoom is one room of the plaza (GET /v1/rooms?q=). A private room is
// Locked: only its name and description are shown, never who made it or
// how many are in it.
export interface PlazaRoom {
  roomId: string;
  name: string;
  description: string;
  visibility: RoomVisibility;
  locked: boolean;
  // Previewable: the room may be read before joining it (a private one
  // still needs an invite code to join).
  previewable: boolean;
  syncMode?: RoomSyncMode;
  createdBy?: string;
  createdAtMs?: number;
  memberCount?: number;
}

// PlazaReply is one page of the plaza: Total rooms match, this page starts
// at Offset and holds at most Limit.
export interface PlazaReply {
  rooms: PlazaRoom[];
  total: number;
  limit: number;
  offset: number;
}

// ChannelUnread is one channel's unread count.
export interface ChannelUnread {
  channelId: string;
  count: number;
}

// UnreadReply is GET /v1/rooms-unread?rooms= (at most MaxUnreadRooms):
// per room, the unread total (a room with none is absent) and the channels
// that have unread messages, default channel first.
export interface UnreadReply {
  unread: Record<string, number>;
  channels: Record<string, ChannelUnread[]>;
}

// UnreadSummary is GET /v1/my/unread: how many of the caller's rooms (in the
// tenant the request is signed for) have unread messages, at most
// MaxUnreadSummaryRooms rooms looked at and UnreadSummaryCap counted. More is
// true when the number is a floor: the cap was reached or the member has more
// rooms than were looked at. It is what an account switcher shows beside an
// account no window shows, so it costs a few index seeks, never a per-room
// request.
export interface UnreadSummary {
  rooms: number;
  more: boolean;
}

// DeletedRooms is GET /v1/my/deleted-rooms?ids= (at most 100): the asked-for
// rooms that were deleted. A live, unknown or never-created id is absent:
// only a deletion is evidence (docs/bugs/2026-10-22-deleted-room-workspaces-never-removed.md).
export interface DeletedRooms {
  deleted: string[];
}

// ---- wire/schedules.go ----

// MaxChatTextBytes is the product cap on one chat message's text. realtime
// enforces it on every post; schedule validation (a room package's
// schedules too) uses the same bound so a stored scheduled prompt always
// fits the post it becomes.
export const MaxChatTextBytes = 16384;

// Schedule recipient kinds: a people-only room message, a message
// addressed to one member's agent (the bridge serving that agent claims it,
// and enforces borrow authorization at drive time exactly as for a typed
// message), or a task in plain words the assist model carries out with the
// room's actions, as the schedule's owner (docs/prd/2026-10-15-app-
// identity-schedules-notify-ai.md §4).
export const ScheduleRecipientRoom = "room";
export const ScheduleRecipientAgent = "agent";
export const ScheduleRecipientAI = "ai";
// ScheduleRecipientNotice is a notice sent at set times, through the
// notification emitter (the one an app's notify uses): where it goes, its
// title and its body are the schedule's own, so a run needs no model to
// say what to do. With Compose the model only writes the body.
export const ScheduleRecipientNotice = "notice";

// Schedule recurrence kinds.
// RecurOnce runs once at AtMs.
export const RecurOnce = "once";
// RecurDaily runs every day at Time (HH:MM) in the schedule's timezone.
export const RecurDaily = "daily";
// RecurWeekly runs on Days (0=Sunday..6=Saturday) at Time.
export const RecurWeekly = "weekly";
// RecurCron runs on a five-field cron-lite expression
// ("minute hour day-of-month month day-of-week").
export const RecurCron = "cron";
// RecurEvent runs when an event it subscribes to happens (Source,
// Types, Filter), never on the clock (docs/prd/2026-10-21-room-events.md).
export const RecurEvent = "event";

// Schedule run outcomes recorded on the schedule (LastStatus).
export const ScheduleRunOK = "ok";
export const ScheduleRunError = "error";
export const ScheduleRunSkipped = "skipped";

// ScheduleRecipient addresses a scheduled message. Kind "room" drives no
// agent; kind "agent" carries the target agent's owner + provider (+ core
// when the owner exposes more than one), or none of them: the schedule
// waits for an agent (a room package's, until its installer picks one of
// theirs) and is never enabled or run (schedule.WaitsForAgent).
export interface ScheduleRecipient {
  kind: ScheduleRecipientKind;
  ownerId?: string;
  provider?: string;
  core?: string;
  // For kind "notice": To is where it goes, as an app's notify says it
  // (AppNotifyRoom, a list of logins, or "group:<name>"); Title is its title
  // and URL an optional link on this deployment. The schedule's text is its
  // body, in which {date}, {week} and the other NoticeVars names stand for the
  // run's own values. With Compose the text is instead what the model is asked
  // to write the body from each run (the destination and title stay fixed).
  to?: unknown;
  title?: string;
  url?: string;
  compose?: boolean;
}

// ScheduleRecurrence is when a schedule fires. Only the fields of its Kind
// are meaningful: AtMs (once), Time (daily, weekly), Days (weekly), Cron
// (cron); for event, the subscription: Source (one of
// EventSubscriptionSources), Types (one or more type patterns: a type, or
// a prefix ending in "*") and an optional Filter.
export interface ScheduleRecurrence {
  kind: RecurrenceKind;
  atMs?: number;
  time?: string;
  days?: number[];
  cron?: string;
  source?: EventSubscriptionSource;
  types?: string[];
  filter?: EventFilter;
}

// EventFilter narrows an event trigger, every field set must hold: the
// event's subject equals Subject, or starts with SubjectPrefix; each Data
// key names a top-level field of the event's data whose value (a string,
// number or boolean, as its JSON text without quotes) equals the given
// one. Equality and prefix only: no expressions.
export interface EventFilter {
  subject?: string;
  subjectPrefix?: string;
  data?: Record<string, string>;
}

// RoomSchedule is one scheduled prompt: Text posted into the room as
// CreatedBy, addressed to Recipient, whenever Recurrence fires in Timezone.
// NextRunAtMs is 0 when the schedule will not fire (paused, or a one-shot
// that already ran).
export interface RoomSchedule {
  scheduleId: string;
  tenantId: string;
  roomId: string;
  channelId?: string;
  createdBy: string;
  text: string;
  recipient: ScheduleRecipient;
  recurrence: ScheduleRecurrence;
  timezone: string;
  enabled: boolean;
  nextRunAtMs?: number;
  lastRunAtMs?: number;
  lastStatus?: ScheduleRunStatus;
  lastError?: string;
  // LastSummary is what an ai schedule's last run did, in a line.
  lastSummary?: string;
  // FailedRuns is how many runs in a row failed (0 after a run that
  // did not).
  failedRuns?: number;
  lastSeq?: number;
  runCount: number;
  createdAtMs: number;
  updatedAtMs: number;
  // Event is the event the schedule's pending (or claimed) run answers:
  // set by the dispatch of an event its trigger takes, cleared when that
  // run completes. A run's text carries it fenced as data
  // (schedule.RunText).
  event?: CloudEvent;
  // Hook is the task's webhook URL (a trigger subscribing to
  // SubscribeWebhook), absent until its creator makes one.
  hook?: ScheduleHook;
  // DroppedEvents counts events the trigger took that a rate limit
  // dropped (the room's owner is told once).
  droppedEvents?: number;
}

// ScheduleRunRequest is realtime's call to the gateway to run an ai
// schedule's slot (POST /internal/v1/schedule-runs): the schedule as
// stored, the slot it runs (the idempotency of what it sends), and DryRun:
// read for real, send nothing, report what it would do.
export interface ScheduleRunRequest {
  schedule: RoomSchedule;
  slotMs: number;
  dryRun?: boolean;
}

// ScheduleRunReply is what an ai run did: its outcome (ScheduleRunStatus),
// its summary (the model's last words), an error a person reads, and the
// actions it took (or, dry, would take).
export interface ScheduleRunReply {
  status: ScheduleRunStatus;
  summary?: string;
  error?: string;
  actions: ScheduleAction[];
  // Seq is the last message the run posted (0: none).
  seq?: number;
}

// ScheduleAction is one action of a run: its name and what it did, in a
// line; DryRun when it was only described.
export interface ScheduleAction {
  name: string;
  detail: string;
  dryRun?: boolean;
}

// ScheduledMarker is set as payload.scheduled on a chat_message the scheduler
// posted, so clients can badge it. A typed message never carries it.
export interface ScheduledMarker {
  scheduleId: string;
}

// ---- wire/search_reindex.go ----

// SearchReindexRequest is the body of POST /v1/platform/search/reindex
// (super-admin, served by realtime): continue the search reindex after
// Cursor ("" = from the start), processing at most MaxBatches batches
// (0 = the server default; the server also caps one call's wall time).
export interface SearchReindexRequest {
  cursor?: string;
  maxBatches?: number;
}

// SearchReindexResponse is one call's progress: the search backend, rows
// read and rows brought into the index in this call (mysql: search text
// filled for rows stored without it; opensearch: documents written), the
// cursor to pass to the next call, and whether the whole feed has been
// walked.
export interface SearchReindexResponse {
  backend: string;
  scanned: number;
  updated: number;
  cursor: string;
  done: boolean;
}

// SearchStatus is GET /v1/platform/search/status (super-admin, served by
// realtime): the search backend and its health as the answering replica
// sees it.
export interface SearchStatus {
  // Backend is "mysql" (the store's FULLTEXT index) or "opensearch".
  backend: string;
  // Index is the OpenSearch index name (opensearch only).
  index?: string;
  // Ready is false while the backend is unreachable or its index is
  // missing and cannot be created.
  ready: boolean;
  // Health is the index's cluster health (green, yellow, red; opensearch
  // only).
  health?: string;
  // Documents is the index's document count (opensearch only).
  documents?: number;
  // Error explains a not-ready backend.
  error?: string;
  // Updates is the answering replica's index update queue (opensearch
  // only: the store index needs none).
  updates?: SearchUpdateStats;
}

// SearchUpdateStats counts one replica's asynchronous index updates since
// it started (messages, not batches).
export interface SearchUpdateStats {
  queued: number;
  applied: number;
  failed: number;
  dropped: number;
}

// ---- wire/service_components.go ----

// TurnService is one service a bridge may call for its turns
// (GET /v1/my/turn-services): its name and the primitives it declared.
