// An agent job's lifecycle status (store.AgentJobStatus).
export type AgentJobStatus = "queued" | "claimed" | "running" | "reflowing" | "replied" | "failed" | "timed_out" | "cancelled";
export const AgentJobStatusValues: readonly AgentJobStatus[] = ["queued", "claimed", "running", "reflowing", "replied", "failed", "timed_out", "cancelled"];
// Why an agent job failed (store.AgentJobFailureReason).
export type AgentJobFailureReason = "no_bridge_online" | "agent_not_advertised" | "borrow_not_authorized" | "core_unavailable" | "runner_start_failed" | "runner_failed" | "agent_error" | "context_overflow" | "context_reset" | "lease_expired" | "sandbox_starting" | "reply_timeout" | "cancelled" | "budget_exhausted" | "budget_unavailable" | "sandbox_required" | "content_unavailable" | "team_unsupported" | "invalid_job";
export const AgentJobFailureReasonValues: readonly AgentJobFailureReason[] = ["no_bridge_online", "agent_not_advertised", "borrow_not_authorized", "core_unavailable", "runner_start_failed", "runner_failed", "agent_error", "context_overflow", "context_reset", "lease_expired", "sandbox_starting", "reply_timeout", "cancelled", "budget_exhausted", "budget_unavailable", "sandbox_required", "content_unavailable", "team_unsupported", "invalid_job"];
// A member's role in a room (store.Role).
export type RoomRole = "owner" | "admin" | "member" | "visitor";
export const RoomRoleValues: readonly RoomRole[] = ["owner", "admin", "member", "visitor"];
// How a room is discovered and joined (store.Visibility).
export type RoomVisibility = "shared" | "private";
export const RoomVisibilityValues: readonly RoomVisibility[] = ["shared", "private"];
// How a room's members converge their code (store.SyncMode).
export type RoomSyncMode = "git" | "mutagen" | "none";
export const RoomSyncModeValues: readonly RoomSyncMode[] = ["git", "mutagen", "none"];
// An organization role as the session carries it (rbac.Role).
export type OrgRole = "super_admin" | "org_admin" | "member" | "viewer";
export const OrgRoleValues: readonly OrgRole[] = ["super_admin", "org_admin", "member", "viewer"];
// A coarse organization permission (rbac.Permission).
export type OrgPermission = "manage_platform" | "manage_org" | "create_room" | "drive_agent" | "read";
export const OrgPermissionValues: readonly OrgPermission[] = ["manage_platform", "manage_org", "create_room", "drive_agent", "read"];
// How a component package runs (pkgmeta.Runtime).
export type ComponentRuntime = "stdio" | "endpoint" | "manifest" | "sidecar" | "bundle";
export const ComponentRuntimeValues: readonly ComponentRuntime[] = ["stdio", "endpoint", "manifest", "sidecar", "bundle"];
// Who gets an installed component (extpipe.Rollout*).
export type ComponentRollout = "auto" | "optin" | "off";
export const ComponentRolloutValues: readonly ComponentRollout[] = ["auto", "optin", "off"];
// A content component kind's short name (the contentpkg registry).
export type ContentKind = "assist" | "expert" | "prompt" | "room" | "skill" | "work";
export const ContentKindValues: readonly ContentKind[] = ["assist", "expert", "prompt", "room", "skill", "work"];

// ---- tables computed by their Go owners ----
// The job statuses store.AgentJobStatus.Terminal reports finished; every
// other status is live (queued or running).
export const AgentJobTerminalStatuses: readonly AgentJobStatus[] = ["replied", "failed", "timed_out", "cancelled"];
// The room roles store.Role.CanInvite admits: they invite and remove
// members and manage the room's content.
export const RoomRolesThatInvite: readonly RoomRole[] = ["owner", "admin"];
// What each organization role may do (rbac.Can). The empty role is a
// session minted without one.
export const OrgRolePermissions: Readonly<Record<OrgRole | "", readonly OrgPermission[]>> = {
  "": ["create_room", "drive_agent", "read"],
  super_admin: ["manage_platform", "manage_org", "create_room", "drive_agent", "read"],
  org_admin: ["manage_org", "create_room", "drive_agent", "read"],
  member: ["create_room", "drive_agent", "read"],
  viewer: ["read"],
};
// The role an unrecognized role string acts as (rbac.Normalize).
export const OrgRoleUnknown: OrgRole = "viewer";
